		}, rt.ArrayItem{ key: 'language', val: 'zh_CN' }, rt.ArrayItem{ key: 'messages', val: rt.create_array([
			rt.ArrayItem{ key: 'start of week1', val: '1' },
			rt.ArrayItem{ key: 'default GMT offset or timezone string0', val: 'Asia/Shanghai' },
			rt.ArrayItem{
				key: 'WordPress continues to polish accessibility across WordPress Core and Gutenberg, advancing the goals to meet accessibility standards. WordPress 7.0 includes fixes across the platform, improving media management, usability for voice control, and improvements to color contrast with the new admin color scheme. The editor ships with new blocks and improvements to editor navigation and interaction.'
				val: 'WordPress 持续优化 WordPress 核心和古腾堡编辑器的无障碍功能，致力于达到无障碍标准。WordPress 7.0 包含全平台的修复，改进了媒体管理功能、语音控制的易用性，并通过新的管理界面配色方案提升了色彩对比度。编辑器新增了多个区块，并对导航和交互功能进行了优化。'
			},
			rt.ArrayItem{
				key: 'WordPress 7.0 improves the accuracy of image loading prioritization, preventing hidden images in navigation overlays or interactive blocks from degrading the loading of critical resources. On-demand block stylesheet loading in classic themes is more reliable, and the ability is added for scripts to depend on script modules to reduce render-blocking.'
				val: 'WordPress 7.0 提高了图片加载优先级的准确性，防止导航覆盖层或交互式区块中的隐藏图片影响关键资源的加载。经典主题中按需加载区块样式表的功能更加可靠，并且新增了脚本依赖脚本模块的功能，以减少阻塞渲染的情况。'
			},
			rt.ArrayItem{
				key: 'Drop a pattern onto your page and it behaves like one block, so you don’t have to hunt through nested blocks for the element you want to change. Swap the text and images, adjust styles from the inspector, and keep moving. For any advanced edits, a single click to "edit pattern" gives you access to all available tools.'
				val: '将一个样板拖放到页面上，它就会像一个独立的区块一样运作，因此您无需在嵌套的区块中费力查找想要修改的元素。只需替换文本和图片，通过检查器调整样式，即可继续操作。若需进行高级编辑，只需单击「编辑样板」，即可使用所有可用工具。'
			},
			rt.ArrayItem{ key: 'Patterns as single blocks.', val: '样板作为独立的区块。' },
			rt.ArrayItem{
				key: 'A simpler way to build with patterns'
				val: '使用样板进行构建的更简便方法'
			},
			rt.ArrayItem{
				key: 'Review your post&#8217;s revision history with a timeline slider and see exactly what changed in the document with visual markers, block by block. Find the version you want and restore it in one click.'
				val: '使用时间轴滑块查看文章的修订历史，并通过可视化标记逐段查看文档的具体修改内容。找到您需要的版本，一键恢复。'
			},
			rt.ArrayItem{
				key: 'Scrub through every version of your page.'
				val: '仔细检查您页面上的每一个版本。'
			},
			rt.ArrayItem{ key: 'Visual revisions', val: '可视化修订版本' },
			rt.ArrayItem{
				key: 'The Connectors screen introduces a single hub for managing a range of external service integrations, including AI providers. Opt in by connecting your preferred AI provider, then put it to work across your site. The optional AI plugin adds a growing set of tools directly into the editor: create titles and excerpts, generate and edit images, and suggest alt text. Any plugin that needs to connect to an outside service can tap into this standardized connection management system, making it easy for users and developers alike.'
				val: '「连接器」界面提供了一个统一的控制中心，用于管理各类外部服务集成，包括 AI 服务提供商。您只需连接首选的 AI 服务提供商即可启用该功能，随后便可将其应用于整个网站。这款可选的 AI 插件将不断扩充的工具集直接集成到编辑器中：生成标题和摘要、创建及编辑图片，以及建议替代文本。任何需要连接外部服务的插件均可接入这一标准化的连接管理系统，从而为用户和开发者带来便利。'
			},
			rt.ArrayItem{
				key: 'A centralized hub for your connections.'
