			rt.ArrayItem{
				key: 'Build the menu overlay you want visitors to see. Go beyond a simple list of links: add columns, increase the font size, and align everything to your liking. Start from a pre-built template, or design your own from scratch.'
				val: '创建您希望访客看到的菜单覆盖层。不要局限于简单的链接列表：添加列、增大字体大小，并按您的喜好调整布局。您可以从现成的模板开始，也可以从零开始设计。'
