				val: 'WordPress 7.0 引入了全平台 AI 基础架构，让您可以接入首选的 AI 服务提供商，并将其应用于整个网站。通过直接套用布局和替换内容，您无需深入操作区块细节，即可实现更简便的编辑体验。导航叠加层现已充分发挥出区块功能的全部潜力。此外，借助可视化对比功能，回顾历史更改也变得更加轻松。'
