			rt.ArrayItem{ key: 'Find your team &rarr;', val: '寻找适合您的团队➡️' },
			rt.ArrayItem{
				key: 'Finding the area that aligns with your skills and interests is the first step toward meaningful contribution. With more than 20 Make WordPress teams working on different parts of the open source WordPress project, there&#8217;s a place for everyone, no matter what your skill set is.'
				val: '找到与您的技能和兴趣相符的领域是做出有意义贡献的第一步。超过 20 个 Make WordPress 团队致力于开源 WordPress 项目的不同部分，无论您的技能水平如何，每个人都能找到自己的一席之地。'
			},
			rt.ArrayItem{
				key: 'Shape the future of the web with WordPress'
				val: '使用 WordPress 塑造网络的未来'
			},
			rt.ArrayItem{
				key: 'WordPress app: Kotlin, Java, Swift, Objective-C, Vue, Python, and TypeScript.'
				val: 'WordPress 应用程序：Kotlin 、 Java 、 Swift 、 Objective-C 、 Vue 、 Python 和 TypeScript'
			},
			rt.ArrayItem{
				key: 'WordPress Core and Block Editor: HTML, CSS, PHP, SQL, JavaScript, and React.'
				val: '核心程序及区块编辑器：HTML 、 CSS 、 PHP 、 SQL 、 JavaScript 及 React'
			},
			rt.ArrayItem{
				key: 'WordPress embraces new technologies, while being committed to backward compatibility. The WordPress project uses the following languages and libraries:'
				val: 'WordPress 拥抱新技术，同时致力于向后兼容。 WordPress 项目使用以下语言和库：'
			},
			rt.ArrayItem{
				key: '<strong>Contribute</strong> to the code, improve the UX, and test the WordPress app.'
				val: '<strong>贡献</strong> 代码、改进用户体验并测试 WordPress 应用。'
			},
			rt.ArrayItem{
				key: '<strong>Write</strong> and submit patches to fix bugs or help build new features.'
				val: '<strong>编写</strong> 并提交补丁以修复错误或帮助构建新功能。'
			},
			rt.ArrayItem{
				key: '<strong>Test</strong> new releases and proposed features for the Block Editor.'
				val: '<strong>测试</strong> 区块编辑器的新版本和建议功能。'
			},
			rt.ArrayItem{
				key: '<strong>Find</strong> and report bugs in the WordPress core software.'
				val: '<strong>查找</strong> 并报告 WordPress 核心软件中的错误。'
			},
			rt.ArrayItem{
				key: 'If you do code, or want to learn how, you can contribute technically in numerous ways:'
				val: '如果您编写代码，或者想学习如何编写代码，您可以通过多种方式做出技术贡献：'
			},
			rt.ArrayItem{ key: 'Code-based contribution', val: '基于代码的贡献' },
			rt.ArrayItem{
				key: '<strong>Explore</strong> ways to reduce the environmental impact of websites.'
				val: '<strong>探索</strong> 减少数百万个网站对环境影响的方法。'
			},
			rt.ArrayItem{
				key: '<strong>Edit</strong> videos and add captions to WordPress.tv.'
				val: '<strong>编辑</strong> 视频并向 WordPress.tv 添加字幕。'
			},
			rt.ArrayItem{
				key: '<strong>Lend</strong> your creative imagination to the WordPress UI design.'
				val: '<strong>发挥</strong> 您的创意想象力到 WordPress UI 设计中。'
			},
			rt.ArrayItem{
				key: '<strong>Organize</strong> or participate in local Meetups and WordCamps.'
				val: '<strong>组织</strong> 或参加本地 WordPress 聚会和 WordCamp。'
			},
			rt.ArrayItem{
				key: '<strong>Curate</strong> submissions or take photos for the Photo Directory.'
				val: '<strong>策划</strong> 提交内容或为 WordPress 照片目录拍摄照片。'
			},
			rt.ArrayItem{
				key: '<strong>Promote</strong> the WordPress project to your community.'
				val: '<strong>推广</strong> 向您的社区 WordPress 项目。'
			},
			rt.ArrayItem{
				key: '<strong>Create</strong> and improve WordPress educational materials.'
				val: '<strong>创建</strong> 并改进 WordPress 教育材料。'
			},
			rt.ArrayItem{
				key: '<strong>Translate</strong> WordPress into your local language.'
				val: '<strong>翻译</strong> 将 WordPress 带入您的本地语言。'
			},
			rt.ArrayItem{
				key: '<strong>Write</strong> or improve documentation for WordPress.'
				val: '<strong>编写</strong> 或改进 WordPress 文档。'
			},
			rt.ArrayItem{
				key: '<strong>Share</strong> your knowledge in the WordPress support forums.'
				val: '<strong>分享</strong> 您的知识在 WordPress 支持论坛。'
			},
			rt.ArrayItem{
				key: 'WordPress may thrive on technical contributions, but you don&#8217;t have to code to contribute. Here are some of the ways you can make an impact without writing a single line of code:'
				val: 'WordPress 可能会因技术贡献而蓬勃发展，但您不必编写代码即可做出贡献。以下是一些无需编写任何代码即可产生影响的方法：'
			},
			rt.ArrayItem{ key: 'No-code contribution', val: '无代码贡献' },
			rt.ArrayItem{
				key: 'Grow your network and make friends.'
				val: '拓展您的网络并结交朋友。'
			},
			rt.ArrayItem{
				key: 'Apply your skills or learn new ones.'
				val: '运用您的技能或学习新技能。'
			},
			rt.ArrayItem{
				key: 'Be part of a global open source community.'
				val: '成为全球开源社区的一部分。'
			},
			rt.ArrayItem{
				key: 'Join the diverse WordPress contributor community and connect with other people who are passionate about maintaining a free and open web.'
				val: '加入 WordPress 贡献者社区，并与热衷于维护自由开放网络的其他人联系。'
			},
			rt.ArrayItem{
				key: 'Do you use WordPress for work, for personal projects, or even just for fun? You can help shape the long-term success of the open source project that powers millions of websites around the world.'
				val: '您使用 WordPress 是为了工作、个人项目，还是只是为了好玩？您可以帮助塑造为全球数百万网站提供支持的开源项目的长期成功。'
			},
			rt.ArrayItem{ key: 'Be the future of WordPress', val: '成为 WordPress 的未来' },
			rt.ArrayItem{
				key: '<a href="%1$s">Learn WordPress</a> is a free resource for new and experienced WordPress users. Learn is stocked with how-to videos on using various features in WordPress, <a href="%2$s">interactive workshops</a> for exploring topics in-depth, and lesson plans for diving deep into specific areas of WordPress.'
				val: '<a href="%1$s">学习 WordPress</a> 是为 WordPress 新用户和经验丰富的用户提供的免费资源。学习包含有关使用 WordPress 中的各种功能的操作视频、用于深入探索主题的<a href="%2$s">互动活动</a>以及用于深入了解 WordPress 特定领域的课程计划。'
			},
			rt.ArrayItem{
				key: '<a href="https://wordpress.org/support/forums/">Support forums</a>'
				val: '<a href="https://cn.wordpress.org/support/forums/">支持论坛</a>'
			},
			rt.ArrayItem{
				key: '<a href="https://wordpress.org/documentation/article/appearance-widgets-screen-classic-editor/">Documentation on Widgets</a>'
				val: '<a href="https://wordpress.org/documentation/article/appearance-widgets-screen-classic-editor/">小工具文档</a>'
			},
			rt.ArrayItem{
				key: '<strong>View</strong> takes you to a public author archive which lists all the posts published by the user.'
				val: '<strong>查看</strong> 带您前往一个公开的作者归档页面，其中列出了由此用户发表的全部文章。'
			},
			rt.ArrayItem{
				key: '<strong>Download file</strong> downloads the original media file to your device.'
				val: '<strong>下载文件</strong> 将下载原始媒体文件到您的设备上。'
			},
			rt.ArrayItem{ key: 'site editor title tagEditor', val: '编辑器' },
			rt.ArrayItem{
				key: '<a href="https://wordpress.org/documentation/article/plugins-themes-auto-updates/">Documentation on Auto-updates</a>'
				val: '<a href="https://wordpress.org/documentation/article/plugins-themes-auto-updates/">关于自动更新的文档</a>'
			},
			rt.ArrayItem{
				key: '<a href="https://wordpress.org/documentation/article/customize-date-and-time-format/">Documentation on date and time formatting</a>.'
				val: '<a href="https://wordpress.org/documentation/article/customize-date-and-time-format/">关于日期和时间格式的文档</a>。'
			},
			rt.ArrayItem{
				key: 'You can set the language, and WordPress will automatically download and install the translation files (available if your filesystem is writable).'
				val: '您可以设置语言，WordPress 将会自动下载并安装翻译文件（如果您的文件系统可写）。'
			},
			rt.ArrayItem{
				key: 'If you want site visitors to be able to register themselves, check the membership box. If you want the site administrator to register every new user, leave the box unchecked. In either case, you can set a default user role for all new users.'
				val: '如果您希望站点的访问者能够自行注册账号，请勾选「成员资格」复选框。如果您希望站点管理员来注册每一个新用户，请将此复选框留空。无论是哪种情况，您都可以为所有新用户设置默认的用户角色。'
			},
			rt.ArrayItem{
				key: 'Both WordPress URL and site URL can start with either %1$s or %2$s. A URL starting with %2$s requires an SSL certificate, so be sure that you have one before changing to %2$s. With %2$s, a padlock will appear next to the address in the browser address bar. Both %2$s and the padlock signal that your site meets some basic security requirements, which can build trust with your visitors and with search engines.'
				val: 'WordPress URL 和站点 URL 都可以以 %1$s 或 %2$s 开头。以 %2$s 开头的 URL 要求 SSL 证书，请确保您在将开头变更为 %2$s 之前，已经安装了对应该地址的 SSL 证书。以 %2$s 开头的 URL，会在浏览器地址栏靠近地址的地方显示一个锁头图标。 %2$s 和锁头图标都表明您的站点已经满足了一些基本的安全要求，意味着您的访客和搜索引擎都可以与您的站点建立可信连接。'
			},
			rt.ArrayItem{
				key: 'Though the terms refer to two different concepts, in practice, they can be the same address or different. For example, you can have the core WordPress installation files in the root directory (<code>https://example.com</code>), in which case the two URLs would be the same. Or the <a href="%s">WordPress files can be in a subdirectory</a> (<code>https://example.com/wordpress</code>). In that case, the WordPress URL and the site URL would be different.'
				val: '尽管这两个项目代表了两个不同的概念，但在实践中它们可以是同一个地址也可以是不同的地址。例如，您可以将 WordPress 核心安装文件放在根目录中（<code>https://example.com</code>），在这种情况下两个 URL 将会保持一致。或者<a href="%s">WordPress 也可以在子目录中</a>（<code>https://example.com/wordpress</code>）。在这种情况下，WordPress URL 和站点 URL 将会不同。'
			},
			rt.ArrayItem{
				key: 'Two terms you will want to know are the WordPress URL and the site URL. The WordPress URL is where the core WordPress installation files are, and the site URL is the address a visitor uses in the browser to go to your site.'
				val: '您需要了解的两个概念是 WordPress URL 与站点 URL。 WordPress URL 是 WordPress 核心安装文件的位置，而站点 URL 是当访客访问您站点时候使用的地址。'
			},
