				val: '<a href="https://wordpress.org/documentation/article/keyboard-shortcuts-classic-editor/#keyboard-shortcuts-for-comments">键盘快捷键文档</a>'
			},
			rt.ArrayItem{
				key: '<a href="https://wordpress.org/documentation/article/understand-comment-spam/">Documentation on Comment Spam</a>'
				val: '<a href="https://wordpress.org/documentation/article/understand-comment-spam/">垃圾评论文档</a>'
			},
			rt.ArrayItem{
				key: '<a href="https://wordpress.org/documentation/article/customizer/">Documentation on Customizer</a>'
				val: '<a href="https://wordpress.org/documentation/article/customizer/">定制器文档</a>'
			},
			rt.ArrayItem{
				key: 'https://wordpress.org/download/'
				val: 'https://cn.wordpress.org/download/'
			},
			rt.ArrayItem{
				key: 'This is the final release of WordPress %s'
				val: '这是 WordPress %s 的最终版本'
			},
			rt.ArrayItem{ key: 'Site Editor', val: '站点编辑器' },
			rt.ArrayItem{
				key: '<strong>Send password reset</strong> sends the user an email with a link to set a new password.'
				val: '<strong>发送密码重置</strong> 将向用户发送一封带有设置新密码链接的邮件。'
			},
			rt.ArrayItem{
				key: 'https://developer.wordpress.org/apis/wp-config-php/#wp-environment-type'
				val: 'https://developer.wordpress.org/apis/wp-config-php/#wp-environment-type'
			},
			rt.ArrayItem{
				key: '<strong>Copy URL</strong> copies the URL for the media file to your clipboard.'
				val: '<strong>复制 URL 到剪贴板</strong> 复制媒体文件的 URL 到您的剪贴板。'
			},
			rt.ArrayItem{
				key: '<strong>View</strong> will take you to a public display page for that file.'
				val: '<strong>查看</strong> 将带您到该文件的公开展示页面。'
			},
			rt.ArrayItem{
				key: '<strong>Delete Permanently</strong> will delete the file from the media library (as well as from any posts to which it is currently attached).'
				val: '<strong>永久删除</strong> 将从媒体库中删除该文件（以及任何附加了该文件的文章中）。'
			},
			rt.ArrayItem{
				key: '<strong>Edit</strong> takes you to a simple screen to edit that individual file&#8217;s metadata. You can also reach that screen by clicking on the media file name or thumbnail.'
				val: '<strong>编辑</strong> 会把您带到一个简单的页面来编辑单独文件的元数据。您也能通过点击文件名称或缩略图来进入这个页面。'
			},
			rt.ArrayItem{
				key: 'Hovering over a row reveals action links that allow you to manage media items. You can perform the following actions:'
				val: '将光标悬停在列表中的某一行上，将显示操作链接使得您可以管理媒体项目。您可以执行以下操作:'
			},
			rt.ArrayItem{ key: 'themesBlock Themes', val: '区块主题' },
			rt.ArrayItem{
				key: '<a href="https://wordpress.org/documentation/article/block-themes/">Documentation on Block Themes</a>'
				val: '<a href="https://wordpress.org/documentation/article/block-themes/">区块主题文档</a>'
			},
			rt.ArrayItem{ key: 'Block themes', val: '区块主题' },
			rt.ArrayItem{
				key: 'With a block theme, you can place and edit blocks without affecting your content by customizing or creating new templates.'
				val: '通过使用区块主题，您将能在不影响您的内容的情况下，通过自定义或新建模版来放置及编辑模块。'
			},
			rt.ArrayItem{
				key: 'A block theme is a theme that uses blocks for all parts of a site including navigation menus, header, content, and site footer. These themes are built for the features that allow you to edit and customize all parts of your site.'
				val: '区块主题是一个可以在站点的所有部分包括导航菜单、页眉、内容以及站点页脚使用区块的主题。这些主题是为了使您能够编辑和定制您的整个站点的特性而设计的。'
			},
			rt.ArrayItem{
				key: 'Recommended items are considered beneficial to your site, although not as important to prioritize as a critical issue. They may include improvements in areas such as security, performance, and user experience.'
				val: '推荐项目对您的站点有益，但其优先级不如关键问题高。这些项目可能包括安全性、性能和用户体验等方面的改进。'
			},
			rt.ArrayItem{
