			rt.ArrayItem{
				key: 'WordPress has been updated! Next and final step is to update your database to the newest version.'
				val: 'WordPress 已更新！下一步也是最后一步是将您的数据库更新到最新版本。'
			},
			rt.ArrayItem{
				key: '<a href="https://wordpress.org/documentation/article/appearance-themes-screen/">Documentation on Managing Themes</a>'
				val: '<a href="https://wordpress.org/documentation/article/appearance-themes-screen/">主题管理文档</a>'
			},
			rt.ArrayItem{
				key: 'This information is being used to create a %s file.'
				val: '这些信息会用于创建 %s 文件。'
			},
			rt.ArrayItem{
				key: 'Welcome to WordPress. Before getting started, you will need to know the following items.'
				val: '欢迎使用 WordPress。在开始之前，您需要了解以下项目。'
			},
			rt.ArrayItem{ key: 'Settings save failed.', val: '设置保存失败。' },
			rt.ArrayItem{
				key: 'After your Privacy Policy page is set, you should edit it.'
				val: '设置隐私政策页面后，您应该对其进行编辑。'
			},
			rt.ArrayItem{
				key: '<strong>Error:</strong> Your %1$s file is not <a href="%2$s">writable</a>, so updating it automatically was not possible. These are the mod_rewrite rules you should have in your %1$s file. Click in the field and press %3$s (or %4$s on Mac) to select all.'
				val: '<strong>错误：</strong>您的 %1$s 文件无法<a href="%2$s">写入</a>，因此无法自动更新。 这些是 %1$s 文件所需的 mod_rewrite 规则。 单击该字段并按下 %3$s（Mac 请按下 %4$s）进行全选。'
			},
			rt.ArrayItem{
				key: '<strong>Error:</strong> Your %1$s file is not <a href="%2$s">writable</a>, so updating it automatically was not possible. This is the URL rewrite rule you should have in your %1$s file. Click in the field and press %3$s (or %4$s on Mac) to select all. Then insert this rule inside of the %5$s element in %1$s file.'
				val: '<strong>错误：</strong>您的 %1$s 文件无法<a href="%2$s">写入</a>，因此无法自动更新。 这是 %1$s 文件中所需的 URL 重写规则。 单击该字段并按下 %3$s（Mac 请按下 %4$s ）进行全选。 然后将此规则插入到 %1$s 文件中的 %5$s 元素内。'
			},
			rt.ArrayItem{
				key: 'An avatar is an image that can be associated with a user across multiple websites. In this area, you can choose to display avatars of users who interact with the site.'
				val: '头像是可以跨多个网站与用户相关联的图片。 在此区域中，您可以选择用户与站点交互显示的头像。'
			},
			rt.ArrayItem{ key: 'Change Permalink Structure', val: '变更固定链接结构' },
			rt.ArrayItem{
				key: 'Howdy,\n\nA site administrator (###USERNAME###) recently requested to have the\nadministration email address changed on this site:\n###SITEURL###\n\nTo confirm this change, please click on the following link:\n###ADMIN_URL###\n\nYou can safely ignore and delete this email if you do not want to\ntake this action.\n\nThis email has been sent to ###EMAIL###\n\nRegards,\nAll at ###SITENAME###\n###SITEURL###'
				val: '您好，\n\n一位站点管理员 (###USERNAME###) 最近要求更改此站点的管理员邮箱地址：\n###SITEURL###\n\n为了确认此次更改，请点击以下链接：\n###ADMIN_URL###\n\n若您不希望进行此次操作，啧可以安全地忽略并删除本邮件。\n\n这封邮件发送至 ###EMAIL###\n\n顺祝\n###SITENAME### 全体成员敬上\n###SITEURL###'
			},
			rt.ArrayItem{ key: 'Where your data is sent', val: '您的数据将发送到何处' },
			rt.ArrayItem{
				key: 'Copy &#8220;%s&#8221; URL to clipboard'
				val: '复制 &#8220;%s&#8221; 的网址到剪贴板'
			},
			rt.ArrayItem{
				key: 'Some data that describes the error your site encountered has been put together.'
				val: '说明此站点遇到问题的数据已进行整理。'
			},
			rt.ArrayItem{
				key: 'An attempt was made, but your site could not be updated automatically.'
				val: '系统已进行尝试，但您的站点无法自动更新。'
			},
			rt.ArrayItem{
				key: 'The update cannot be installed because some files could not be copied. This is usually due to inconsistent file permissions.'
				val: '由于某些文件无法被复制，更新无法进行。此问题通常是由于文件权限不一致造成的。'
			},
			rt.ArrayItem{
				key: '<strong>Media</strong> &mdash; A list of URLs for media files the user uploads.'
				val: '<strong>媒体</strong> — 用户上传的全部媒体文件的网址列表。'
			},
			rt.ArrayItem{
				key: '<strong>Community Events Location</strong> &mdash; The IP Address of the user, which populates the Upcoming Community Events dashboard widget with relevant information.'
				val: '<strong>社区活动位置</strong> — 会使用用户的 IP 地址在「即将举行的社区活动」仪表盘小工具中填充相关信息。'
			},
			rt.ArrayItem{
				key: 'WordPress collects (but <em>never</em> publishes) a limited amount of data from registered users who have logged in to the site. Generally, these users are people who contribute to the site in some way -- content, store management, and so on. With rare exceptions, these users do not include occasional visitors who might have registered to comment on articles or buy products. The data WordPress retains can include:'
				val: 'WordPress 从登录此站点的注册用户处收集（但绝不会公布）有限的数据。 通常，这些用户是以某种方式（如内容、商店管理等）作出贡献的人员；除极少数例外，这些用户不包含可能注册发表评论、发布文章或购买商品的常规访问者。 WordPress 保留的数据列举如下：'
			},
			rt.ArrayItem{
				key: 'Note: Since this tool only gathers data from WordPress and participating plugins, you may need to do more to comply with export requests. For example, you should also send the requester some of the data collected from or stored with the 3rd party services your organization uses.'
				val: '注意：由于此工具仅收集 WordPress 及规范插件的数据，您可能需要采取更多措施来遵守导出请求。 例如，您还有责任向请求者发送您的组织使用的第三方服务收集或存储的数据。'
			},
			rt.ArrayItem{
				key: 'Privacy Laws around the world require businesses and online services to provide an export of some of the data they collect about an individual, and to deliver that export on request. The rights those laws enshrine are sometimes called the "Right of Data Portability". It allows individuals to obtain and reuse their personal data for their own purposes across different services. It allows them to move, copy or transfer personal data easily from one IT environment to another.'
				val: '世界各地的隐私法要求企业和在线服务提供收集的个人相关数据的导出功能，并应要求提供该导出功能。 这些法律所赋予的权利有时被称为「数据可移植性权利」。 此项权利能让个人在不同的服务中为自己的目的获取和重用他们的个人数据，并允许让用户轻松地将个人数据从一个 IT 环境移动、复制或传输到另一个 IT 环境。'
			},
			rt.ArrayItem{
				key: '<strong>Comments</strong> &mdash; WordPress does not delete comments. The software does anonymize (but, again, <em>never</em> publishes) the associated Email Address, IP Address, and User Agent (Browser/OS).'
				val: '<strong>评论</strong> — WordPress 不会删除评论。 该软件会匿名化（但绝不会公布）评论者的相关邮箱地址、 IP 地址和用户代理（浏览器 / 操作系统）。'
			},
			rt.ArrayItem{
				key: 'WordPress collects (but <em>never</em> publishes) a limited amount of data from logged-in users but then deletes it or anonymizes it. That data can include:'
				val: 'WordPress 从登录用户处收集（但绝不会公布）有限的数据，随后会将其删除或匿名化，这些数据列举如下：'
			},
			rt.ArrayItem{
				key: 'Note: As this tool only gathers data from WordPress and participating plugins, you may need to do more to comply with erasure requests. For example, you are also responsible for ensuring that data collected by or stored with the 3rd party services your organization uses gets deleted.'
				val: '注意：由于此工具仅收集 WordPress 及规范插件的数据，您可能需要采取更多措施来遵守抹除请求。 例如，您还有责任确保删除您的组织使用的第三方服务收集或存储的数据。'
			},
			rt.ArrayItem{
				key: 'Privacy Laws around the world require businesses and online services to delete, anonymize, or forget the data they collect about an individual. The rights those laws enshrine are sometimes called the "Right to be Forgotten".'
				val: '世界各地的隐私法要求企业和在线服务提供删除、匿名化或抹除已收集的个人数据的功能，这些法律所赋予的权利有时被称为「被遗忘权」。'
			},
			rt.ArrayItem{
				key: 'This screen is where you manage requests to erase personal data.'
				val: '此界面用于管理抹除个人数据的请求。'
			},
			rt.ArrayItem{
				key: 'This post is being backed up in your browser, just in case.'
				val: '以防万一，此文章已在您的浏览器中进行备份。'
			},
			rt.ArrayItem{
				key: 'This will grant access to <a href="%1$s">the %2$s site on the network as you have Super Admin rights</a>.'
