			rt.ArrayItem{
				key: '<strong>Format</strong> &mdash; Post Formats designate how your theme will display a specific post. For example, you could have a <em>standard</em> blog post with a title and paragraphs, or a short <em>aside</em> that omits the title and contains a short text blurb. Your theme could enable all or some of 10 possible formats. <a href="https://developer.wordpress.org/advanced-administration/wordpress/post-formats/#supported-formats">Learn more about each post format</a>.'
				val: '<strong>形式</strong>——文章形式规定了您的主题将显示一篇文章的方式。比如，您可以有一篇「标准」的文章，其包括标题和几个段落；也可以有一篇短小的「旁白」，略去标题而只有短短一段文字。您的主题可以启用 10 种可用的文章形式的全部或一部分。<a href="https://developer.wordpress.org/advanced-administration/wordpress/post-formats/#supported-formats">了解更多有关各种文章形式的信息</a>。'
