			rt.ArrayItem{
				key: 'Deleting a category does not delete the posts in that category. Instead, posts that were only assigned to the deleted category are set to the default category %s. The default category cannot be deleted.'
				val: '删除分类不会删除分类中的文章。然而，仅隶属于已删除分类的文章将会分入默认分类 %s 中。默认分类不能被删除。'
