			},
			rt.ArrayItem{
				key: 'To distribute copies of your modified versions to others.'
				val: '将经过您修改的版本重新分发给其他人。'
			},
			rt.ArrayItem{ key: 'The 4th Freedom', val: '自由之四' },
			rt.ArrayItem{ key: 'To redistribute.', val: '将程序重新分发。' },
			rt.ArrayItem{ key: 'The 3rd Freedom', val: '自由之三' },
			rt.ArrayItem{
				key: 'To study how the program works and change it to make it do what you wish.'
				val: '研究程序的工作原理并对其进行修改以使其按照您的意愿运行。'
			},
			rt.ArrayItem{ key: 'The 2nd Freedom', val: '自由之二' },
			rt.ArrayItem{
				key: 'To run the program for any purpose.'
				val: '可将程序运行于任何用途。'
			},
			rt.ArrayItem{ key: 'The 1st Freedom', val: '自由之一' },
			rt.ArrayItem{ key: 'Created', val: '创建日期' },
			rt.ArrayItem{
				key: 'Welcome to WordPress. This is your first post. Edit or delete it, then start writing!'
				val: '欢迎使用 WordPress。这是您的第一篇文章。编辑或删除它，然后开始写作吧！'
			},
			rt.ArrayItem{
				key: 'As a new WordPress user, you should go to <a href="%s">your dashboard</a> to delete this page and create new pages for your content. Have fun!'
				val: '而您，作为一位 WordPress 新用户，我们建议您转到<a href="%s">您站点的仪表盘</a>，删除本页面，然后创建包含您自己内容的新页面。祝您使用愉快！'
			},
			rt.ArrayItem{
				key: 'The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.'
				val: 'XYZ Doohickey 公司成立于 1971 年，自从建立以来，我们一直向社会贡献着优秀 doohickies。我们的公司总部位于天朝魔都，有着超过两千名员工，对魔都政府税收有着巨大贡献。'
			},
			rt.ArrayItem{ key: '...or something like this:', val: '……或这个：' },
			rt.ArrayItem{
				key: "Hi there! I'm a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin' caught in the rain.)"
				val: '大家好！ 我白天是一名快递小哥，晚上是一名有抱负的魔术师，这是我的网站。 我住在北京，养了一只名叫二哈的小狗。 我平时喜欢喝可乐，还有遛狗。'
			},
			rt.ArrayItem{
				key: "This is an example page. It's different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:"
				val: '这是示范页面。页面和博客文章不同，它的位置是固定的，通常会在站点导航栏显示。很多用户都创建一个「关于」页面，向访客介绍自己。例如：'
			},
			rt.ArrayItem{ key: 'Export &#8220;%s&#8221; as JSON', val: '导出「%s」为 JSON' },
			rt.ArrayItem{
				key: '1 pattern not updated, somebody is editing it.'
				val: '未更新 1 个区块，有人正在编辑。'
			},
			rt.ArrayItem{
				key: '%s pattern restored from the Trash.'
				val: '已从回收站还原 %s 个区块。'
			},
			rt.ArrayItem{
				key: '<strong>Error:</strong> "Table Prefix" must not be empty.'
				val: '<strong>错误：</strong>「表前缀」不能为空。'
			},
			rt.ArrayItem{
				key: 'This meta box, from the %s plugin, is not compatible with the block editor.'
				val: '%s 插件的元数据模块不兼容区块编辑器。'
			},
			rt.ArrayItem{ key: 'personal data group labelAbout', val: '关于' },
			rt.ArrayItem{ key: 'page titleAbout', val: '关于' },
			rt.ArrayItem{
				key: '<a href="%1$s">Edit</a> or <a href="%2$s">preview</a> your Privacy Policy page content.'
				val: '<a href="%1$s">编辑</a>或<a href="%2$s">预览</a>您的隐私政策页面内容。'
			},
			rt.ArrayItem{ key: 'Privacy Policy Page', val: '隐私政策页' },
			rt.ArrayItem{ key: '%s (Draft)', val: '%s（草稿）' },
			rt.ArrayItem{
				key: 'Privacy Policy page updated successfully.'
				val: '已成功更新隐私政策页面。'
			},
			rt.ArrayItem{
				key: 'The suggested privacy policy content should be added by using the %s (or later) action. Please see the inline documentation.'
				val: '推荐的隐私政策内容只应在 wp-admin 中通过 %s（或之后的）动作加入。请查阅内联文档。'
			},
			rt.ArrayItem{
				key: 'The suggested privacy policy content should be added only in wp-admin by using the %s (or later) action.'
				val: '推荐的隐私政策内容只应在 wp-admin 中通过 %s（或之后的）动作加入。'
			},
			rt.ArrayItem{
				key: 'The suggested privacy policy text has changed. Please <a href="%s">review the guide</a> and update your privacy policy.'
				val: '推荐的隐私政策文本已发生改动。请<a href="%s">浏览指南页面</a>并更新您的隐私政策。'
			},
			rt.ArrayItem{ key: 'There are no pages.', val: '没有页面。' },
			rt.ArrayItem{
				key: 'Need help putting together your new Privacy Policy page? <a href="%1$s" %2$s>Check out the privacy policy guide%3$s</a> for recommendations on what content to include, along with policies suggested by your plugins and theme.'
				val: '创建您的隐私政策页面时如需帮助，<a href="%1$s" %2$s>请查阅《隐私政策指南》 %3$s</a>，了解隐私政策页面应包含哪些内容，并查阅您所安装的插件、主题所推荐的隐私政策内容。'
			},
			rt.ArrayItem{ key: 'Privacy Policy Guide', val: '《隐私政策指南》' },
			rt.ArrayItem{
				key: 'Visitor comments may be checked through an automated spam detection service.'
				val: '访客评论可能会被自动垃圾评论监测服务检查。'
			},
			rt.ArrayItem{
				key: 'In this subsection you should note what analytics package you use, how users can opt out of analytics tracking, and a link to your analytics provider&#8217;s privacy policy, if any.'
				val: '在此章节中，您应该说明您使用何种统计程序软件包，用户选择退出统计跟踪的方式，以及指向您统计服务提供商隐私政策的链接。'
			},
			rt.ArrayItem{
				key: 'In this subsection you should note what information may be disclosed by users who can upload media files. All uploaded files are usually publicly accessible.'
				val: '在此章节中，您应当表明用户在上传媒体文件时会披露何种信息。通常来说，所有已上传的文件都是公开可访问的。'
			},
			rt.ArrayItem{
				key: 'In this subsection you should note what information is captured through comments. We have noted the data which WordPress collects by default.'
				val: '在此章节中，您应当表明您在用户留下评论时收集何种信息。我们已将 WordPress 默认收集的信息列举如下。'
			},
			rt.ArrayItem{
				key: 'In this section you should note what personal data you collect from users and site visitors. This may include personal data, such as name, email address, personal account preferences; transactional data, such as purchase information; and technical data, such as information about cookies.'
				val: '在此章节中，您应当列出您从站点用户和访问者处收集哪些个人数据，这可能包括如姓名、邮箱地址、个人账户设置等个人数据，如购买信息等交易数据、 Cookies 中所包含的信息等技术数据。'
			},
			rt.ArrayItem{ key: 'Suggested text:', val: '推荐的文本：' },
			rt.ArrayItem{
				key: 'The template contains a suggestion of sections you most likely will need. Under each section heading, you will find a short summary of what information you should provide, which will help you to get started. Some sections include suggested policy content, others will have to be completed with information from your theme and plugins.'
				val: '该模板包含您可能需要用到的章节的建议，宁会在每个章节的标题下找到应提供哪些信息的简短摘要，这些摘要将有助于您快速开始撰写。 部分章节包含了我们推荐的政策内容，剩余章节必须使用您的主题和插件提供的信息来完成。'
			},
			rt.ArrayItem{ key: 'Updated %s.', val: '已更新 %s。' },
			rt.ArrayItem{
				key: 'You deactivated this plugin on %s and may no longer need this policy.'
				val: '您在 %s 禁用了此插件，因此您可能已经不需要此政策。'
			},
			rt.ArrayItem{ key: 'Removed %s.', val: '已移除 %s。' },
			rt.ArrayItem{ key: 'Introduction', val: '介绍' },
			rt.ArrayItem{
				key: 'Need help putting together your new Privacy Policy page? Check out the guide for recommendations on what content to include, along with policies suggested by your plugins and theme.'
				val: '需要帮助来创建您的隐私政策页面？请查阅指南来看看应该包括哪些内容，还有您的插件和主题推荐的政策。'
			},
			rt.ArrayItem{ key: 'Erasing data...', val: '正在抹除数据…' },
			rt.ArrayItem{ key: 'Add Data Erasure Request', val: '加入数据抹除请求' },
			rt.ArrayItem{ key: 'Send export link', val: '发送资料导出链接' },
			rt.ArrayItem{
				key: 'If you are a member of a regulated industry, or if you are subject to additional privacy laws, you may be required to disclose that information here.'
				val: '如果您属于受法律监管的行业，或您受到其他隐私法律的管辖，您可能需要在此披露这些信息。'
			},
			rt.ArrayItem{
				key: 'Industry regulatory disclosure requirements'
				val: '行业监管披露要求'
			},
			rt.ArrayItem{
				key: 'If your website provides a service which includes automated decision making - for example, allowing customers to apply for credit, or aggregating their data into an advertising profile - you must note that this is taking place, and include information about how that information is used, what decisions are made with that aggregated data, and what rights users have over decisions made without human intervention.'
				val: '如果您的网站提供包含自动决策的服务，如允许客户申请信用卡、或收集客户信息进入广告资料，您必须明示这些事件的发生，并说明信息如何被使用，通过何种汇总数据进行了何种决策，及在决策不受人工干预作出时用户有哪些权利。'
			},
			rt.ArrayItem{
				key: 'What automated decision making and/or profiling we do with user data'
				val: '我们通过用户数据进行何种自动决策及（或）归纳'
			},
			rt.ArrayItem{
				key: 'If your website receives data about users from third parties, including advertisers, this information must be included within the section of your privacy policy dealing with third party data.'
				val: '如果您的网站从第三方，如广告商，接收关于用户的数据，这些信息必须在您的隐私政策中涉及到第三方数据的章节予以体现。'
			},
			rt.ArrayItem{
				key: 'What third parties we receive data from'
				val: '我们从哪些第三方接收数据'
			},
			rt.ArrayItem{
				key: 'In this section you should explain what procedures you have in place to deal with data breaches, either potential or real, such as internal reporting systems, contact mechanisms, or bug bounties.'
				val: '在此章节中，您应当说明您采取何种流程处理实际出现或潜在的数据泄露，如内部报告系统、联系机制及软件缺陷赏金计划等。'
			},
			rt.ArrayItem{
				key: 'What data breach procedures we have in place'
				val: '我们有何种数据泄露处理流程'
			},
			rt.ArrayItem{
				key: 'In this section you should explain what measures you have taken to protect your users&#8217; data. This could include technical measures such as encryption; security measures such as two factor authentication; and measures such as staff training in data protection. If you have carried out a Privacy Impact Assessment, you can mention it here too.'
				val: '在此章节中，您应当解释您使用了何种措施来保护用户的数据。这包括了技术手段（例如加密）、安全手段（例如双因素身份验证）及其他措施（例如要求职员参加数据保护培训）。若您已经完成数据保护影响评估（Privacy Impact Assessment），也可在此提及。'
			},
			rt.ArrayItem{ key: 'How we protect your data', val: '我们如何保护您的数据' },
			rt.ArrayItem{
				key: 'If you use your site for commercial purposes and you engage in more complex collection or processing of personal data, you should note the following information in your privacy policy in addition to the information we have already discussed.'
				val: '如果您将您的站点用于商业活动，且您进行了更复杂的个人数据收集及处理，您应当在您的隐私政策中写下以下信息。'
			},
			rt.ArrayItem{ key: 'Additional information', val: '其他信息' },
			rt.ArrayItem{
				key: 'In this section you should provide a contact method for privacy-specific concerns. If you are required to have a Data Protection Officer, list their name and full contact details here as well.'
				val: '在此章节中，您应当留下处理隐私相关问题的联系方式。如果您依法规设有数据保护官（Data Protection Officer），请留下其姓名和完整联系方式。'
			},
			rt.ArrayItem{
				key: 'European data protection law requires data about European residents which is transferred outside the European Union to be safeguarded to the same standards as if the data was in Europe. So in addition to listing where data goes, you should describe how you ensure that these standards are met either by yourself or by your third party providers, whether that is through an agreement such as Privacy Shield, model clauses in your contracts, or binding corporate rules.'
				val: '欧盟的数据保护法规要求，所有关于欧盟居民的数据，如有被转移出欧盟，必须受到与在欧盟内相同等级的保护。因此，除了列出这些数据的去向外，您也需要描述您或您的第三方提供商如何符合这些标准，如通过隐私盾（Privacy Shield）或类似协议、格式合同条款或具备约束性的公司规则。'
			},
			rt.ArrayItem{
				key: 'In this section you should list all transfers of your site data outside the European Union and describe the means by which that data is safeguarded to European data protection standards. This could include your web hosting, cloud storage, or other third party services.'
				val: '在此章节中，您应当列出所有将您的站点数据移出欧盟的行为，并描述这些数据受到了何种符合欧洲数据保护标准的保护方式。这些数据可能包括了您网站使用的虚拟主机、云存储及其他第三方服务。'
			},
			rt.ArrayItem{
				key: 'If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.'
				val: '如果您有此站点的账户，或曾经留下评论，您可以请求我们提供我们所拥有的您的个人数据的导出文件，这也包括了所有您提供给我们的数据。您也可以要求我们抹除所有关于您的个人数据。这不包括我们因管理、法规或安全需要而必须保留的数据。'
			},
			rt.ArrayItem{
				key: 'In this section you should explain what rights your users have over their data and how they can invoke those rights.'
				val: '在此章节中，您应当解释用户对于其个人数据所拥有的权利及他们行使权利的方式。'
			},
			rt.ArrayItem{
				key: 'What rights you have over your data'
				val: '您对您的信息有什么权利'
			},
			rt.ArrayItem{
				key: 'For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.'
				val: '对于本网站的注册用户，我们也会保存用户在个人资料中提供的个人信息。所有用户可以在任何时候查看、编辑或删除他们的个人信息（除了不能变更用户名外）、站点管理员也可以查看及编辑那些信息。'
			},
			rt.ArrayItem{
				key: 'If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.'
				val: '如果您留下评论，评论和其元数据将被无限期保存。我们这样做以便能识别并自动批准任何后续评论，而不用将这些后续评论加入待审队列。'
			},
			rt.ArrayItem{
				key: 'In this section you should explain how long you retain personal data collected or processed by the website. While it is your responsibility to come up with the schedule of how long you keep each dataset for and why you keep it, that information does need to be listed here. For example, you may want to say that you keep contact form entries for six months, analytics records for a year, and customer purchase records for ten years.'
				val: '在此章节中，您应当指出由网站收集或处理的个人数据的保留期限。尽管您有责任决定数据集的保存期限及保存原因，您也需要将这些信息列在此处。例如，您可以说明，您会保留联系表单条目六个月、保留统计记录一年、保留客户购买记录十年等。'
			},
			rt.ArrayItem{ key: 'How long we retain your data', val: '我们保留多久您的信息' },
			rt.ArrayItem{
				key: 'By default WordPress does not share any personal data with anyone.'
				val: 'WordPress 默认不会与任何人共享任何个人数据。'
			},
			rt.ArrayItem{
				key: 'In this section you should name and list all third party providers with whom you share site data, including partners, cloud-based services, payment processors, and third party service providers, and note what data you share with them and why. Link to their own privacy policies if possible.'
				val: '在此章节中，您应当列出您共享站点数据的所有第三方提供商，包括合作伙伴、云服务、支付服务及其他第三方服务提供商。您应当写明您与他们共享数据的种类及共享的原因。如果可能，您也应该提供指向他们隐私政策的链接。'
			},
			rt.ArrayItem{ key: 'Who we share your data with', val: '我们与谁共享您的信息' },
			rt.ArrayItem{
				key: 'By default WordPress does not collect any analytics data. However, many web hosting accounts collect some anonymous analytics data. You may also have installed a WordPress plugin that provides analytics services. In that case, add information from that plugin here.'
				val: 'WordPress 默认不会收集统计数据，但许多虚拟主机账户会收集匿名的统计数据。如果您安装了提供统计服务的 WordPress 插件，请将这些插件的信息列在此处。'
			},
			rt.ArrayItem{ key: 'Analytics', val: '统计' },
			rt.ArrayItem{
				key: 'These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.'
				val: '这些站点可能会收集关于您的数据、使用 Cookies 、嵌入额外的第三方跟踪程序及监视您与这些嵌入内容的交互，包括在您有这些站点的账户并登录了这些站点时，跟踪您与嵌入内容的交互。'
			},
			rt.ArrayItem{
				key: 'Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.'
				val: '此站点上的文章可能会包含嵌入的内容（如视频、图片、文章等）。来自其他站点的嵌入内容的行为和您直接访问这些其他站点没有区别。'
			},
			rt.ArrayItem{
				key: 'Embedded content from other websites'
				val: '来自其他网站的嵌入内容'
			},
			rt.ArrayItem{
				key: 'If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.'
				val: '如果您编辑或发布文章，我们会在您的浏览器中保存一个额外的 Cookie。这个 Cookie 不包含个人数据而只记录了您刚才编辑的文章的 ID。这个 Cookie 会保留一天。'
			},
			rt.ArrayItem{
				key: 'When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.'
				val: '当您登录时，我们也会设置多个 Cookies 来保存您的登录信息及屏幕显示选项。登录 Cookies 会保留两天，而屏幕显示选项 Cookies 会保留一年。如果您选择了「记住我」，您的登录状态则会保留两周。如果您注销登陆了您的账户，用于登录的 Cookies 将会被移除。'
			},
			rt.ArrayItem{
				key: 'If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.'
				val: '如果您访问我们的登录页，我们会设置一个临时的 Cookie 来确认您的浏览器是否接受 Cookies。此 Cookie 不包含个人数据，且会在您关闭浏览器时被丢弃。'
			},
			rt.ArrayItem{
				key: 'If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.'
				val: '如果您在我们的站点上留下评论，您可以选择用 Cookies 保存您的名字、邮箱地址和网站地址。这是通过让您可以不用在评论时再次填写相关内容而向您提供方便。这些 Cookies 会保留一年。'
			},
			rt.ArrayItem{
				key: 'In this subsection you should list the cookies your website uses, including those set by your plugins, social media, and analytics. We have provided the cookies which WordPress installs by default.'
				val: '在此章节中，您应当列出您的站点所使用的 Cookies，这也包括您的插件、社交媒体和统计程序所设置的 Cookies。我们已经为您列出了 WordPress 默认使用的 Cookies。'
			},
			rt.ArrayItem{ key: 'Cookies', val: 'Cookies' },
			rt.ArrayItem{
				key: 'An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.'
				val: '由您的邮箱地址所生成的匿名化字符串（又称为哈希）可能会被提供给 Gravatar 服务确认您是否有使用该服务。 Gravatar 服务的隐私政策在此：https://automattic.com/privacy/。在您的评论获批准后，您的资料图片将在您的评论旁公开展示。'
			},
			rt.ArrayItem{
				key: 'When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.'
				val: '当访客留下评论时，我们会收集评论表单所显示的数据，和访客的 IP 地址及浏览器的 User-Agent 字符串来帮助检查垃圾评论。'
			},
			rt.ArrayItem{
				key: 'By default, WordPress does not include a contact form. If you use a contact form plugin, use this subsection to note what personal data is captured when someone submits a contact form, and how long you keep it. For example, you may note that you keep contact form submissions for a certain period for customer service purposes, but you do not use the information submitted through them for marketing purposes.'
				val: 'WordPress 默认并不提供联系表单。如果您使用了联系表单插件，请在此章节表明您在访客提交联系表单时所收集个人数据的种类及保留期限。例如，您可以说明，您会将所有提交的联系表单保留一段时间以供客户服务之用，但您不会将这些信息用于市场宣传。'
			},
			rt.ArrayItem{ key: 'Contact forms', val: '联系表单' },
			rt.ArrayItem{
				key: 'If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.'
				val: '如果您向此网站上传图片，您应当避免上传那些有嵌入地理位置信息（EXIF GPS）的图片。此网站的访客将可以下载并提取此网站的图片中的位置信息。'
			},
			rt.ArrayItem{
				key: 'By default WordPress does not collect any personal data about visitors, and only collects the data shown on the User Profile screen from registered users. However some of your plugins may collect personal data. You should add the relevant information below.'
				val: 'WordPress 默认不会收集关于访客的任何个人数据，而只会收集关于注册用户的，在用户资料页面显示的数据。但是您安装的一些插件可能会收集个人数据。您应该在下面加入相关信息。'
			},
			rt.ArrayItem{
				key: 'Personal data is not just created by a user&#8217;s interactions with your site. Personal data is also generated from technical processes such as contact forms, comments, cookies, analytics, and third party embeds.'
				val: '个人数据不仅由用户与您的站点的交互而产生，也会由其他技术过程产生，例如联系表单、评论、 Cookies 、统计和第三方嵌入内容等。'
			},
			rt.ArrayItem{
				key: 'In addition to listing what personal data you collect, you need to note why you collect it. These explanations must note either the legal basis for your data collection and retention or the active consent the user has given.'
				val: '在列出您收集的个人数据之外，您也需要表明您为何收集这些信息。这里的说明必须指出您的数据收集及保留的法律基础，或有无获得用户同意。'
			},
			rt.ArrayItem{
				key: 'You should also note any collection and retention of sensitive personal data, such as data concerning health.'
				val: '您也应该表明您如何收集及存放敏感的个人数据，例如与健康相关的数据。'
			},
			rt.ArrayItem{
				key: 'What personal data we collect and why we collect it'
				val: '我们收集何种及为何收集个人数据'
			},
			rt.ArrayItem{
				key: 'Our website address is: %s.'
				val: '我们的站点地址是：%s。'
			},
			rt.ArrayItem{
				key: 'The amount of information you may be required to show will vary depending on your local or national business regulations. You may, for example, be required to display a physical address, a registered address, or your company registration number.'
				val: '此章节中，所需的信息的多少将取决于您所在国家或地区的商业法规要求。例如，您有可能需要展示您的实际地址、注册地址或公司注册代码。'
			},
			rt.ArrayItem{
				key: 'In this section you should note your site URL, as well as the name of the company, organization, or individual behind it, and some accurate contact information.'
				val: '在此章节中，您应当列出您的站点 URL 、主办站点的公司、组织或个人及准确的联系信息。'
			},
			rt.ArrayItem{ key: 'Who we are', val: '我们是谁' },
			rt.ArrayItem{
				key: 'It is your responsibility to write a comprehensive privacy policy, to make sure it reflects all national and international legal requirements on privacy, and to keep your policy current and accurate.'
				val: '您有责任编写周全的隐私政策。您需要确保您的隐私政策符合所有国内法和国际隐私法规要求，及时更新您的政策，并力求其准确。'
			},
			rt.ArrayItem{
				key: 'Please edit your privacy policy content, making sure to delete the summaries, and adding any information from your theme and plugins. Once you publish your policy page, remember to add it to your navigation menu.'
				val: '请编辑您的隐私政策内容、删除范本提供的摘要内容并为您的主题和插件加入所需的内容。在您发布您的政策页面之后，请记得将其加入网站的导航菜单。'
			},
			rt.ArrayItem{
				key: 'This text template will help you to create your website&#8217;s privacy policy.'
				val: '此文字模板能够帮助您创建网站的隐私政策。'
			},
			rt.ArrayItem{
				key: 'As a website owner, you may need to follow national or international privacy laws. For example, you may need to create and display a privacy policy.'
				val: '作为网站所有者，您可能需要遵守国内或国际隐私法律。例如，您可能需要创建并展示隐私政策。'
			},
