			rt.ArrayItem{ key: 'Invalid request type.', val: '无效的请求类型。' },
			rt.ArrayItem{ key: 'Use This Page', val: '使用本页' },
			rt.ArrayItem{ key: 'Select a Privacy Policy page', val: '选择隐私政策页面' },
			rt.ArrayItem{
				key: 'Change your Privacy Policy page'
				val: '更改您的隐私政策页面'
			},
			rt.ArrayItem{
				key: '<a href="%1$s">Edit</a> or <a href="%2$s">view</a> your Privacy Policy page content.'
				val: '<a href="%1$s">编辑</a>或<a href="%2$s">查看</a>您的隐私政策页面内容。'
			},
			rt.ArrayItem{
				key: 'You should also review your privacy policy from time to time, especially after installing or updating any themes or plugins. There may be changes or new suggested information for you to consider adding to your policy.'
				val: '我们建议您不时回顾您的隐私政策，尤其是在安装或更新任何主题或插件之后。 这两者可能会有新的更改或建议信息需要添加到政策中。'
			},
			rt.ArrayItem{
				key: 'However, it is your responsibility to use those resources correctly, to provide the information that your privacy policy requires, and to keep that information current and accurate.'
				val: '但是，您有责任正确使用这些资源，以提供您的隐私政策所需的信息，确保信息的时效性和准确性。'
			},
			rt.ArrayItem{
