				val: '您好：\n\n您请求的个人数据导出已经完成。您可以通过点击以下链接来下载您的个人信息。\n为了隐私和安全，我们会在 ###EXPIRATION### 删除这些文件，\n所以请在此日期前下载。\n\n###LINK###\n\n祝好，\n###SITENAME### 敬上\n###SITEURL###'
