			rt.ArrayItem{ key: 'Requires PHP Version:', val: '要求 PHP 版本：' },
			rt.ArrayItem{
				key: 'This data is used to provide general enhancements to WordPress, which includes helping to protect your site by finding and automatically installing new updates. It is also used to calculate statistics, such as those shown on the <a href="%s">WordPress.org stats page</a>.'
				val: '这些数据会被用来改善 WordPress，包括通过为您寻找并自动安装更新来保护您的站点。这些数据也会被用来计算统计，比如显示在 <a href="%s">WordPress.org 统计页面</a> 上的数据。'
			},
			rt.ArrayItem{
				key: 'There is no need to change your CSS here &mdash; you can edit and live preview CSS changes in the <a href="%s">built-in CSS editor</a>.'
				val: '无需在此处更改 CSS — 您可以在<a href="%s">内置 CSS 编辑器</a>中编辑和实时预览 CSS 更改。'
			},
			rt.ArrayItem{ key: 'Did you know?', val: '您知道吗？' },
			rt.ArrayItem{ key: 'Noteworthy Contributors', val: '值得注意的贡献者' },
			rt.ArrayItem{
				key: 'If you decide to go ahead with direct edits anyway, use a file manager to create a copy with a new name and hang on to the original. That way, you can re-enable a functional version if something goes wrong.'
				val: '如果您仍要直接进行修改，请使用资源管理器将文件复制一份并保留修改前的版本。这样当出现问题时您就能恢复到正常的版本。'
			},
			rt.ArrayItem{
				key: 'If you absolutely have to make direct edits to this plugin, use a file manager to create a copy with a new name and hang on to the original. That way, you can re-enable a functional version if something goes wrong.'
				val: '如果您必须直接修改此插件，请使用资源管理器将文件复制一份并保留修改前的版本。这样当出现问题时您就能恢复到正常的版本。'
			},
			rt.ArrayItem{
				key: 'You appear to be making direct edits to your plugin in the WordPress dashboard. Editing plugins directly is not recommended as it may introduce incompatibilities that break your site and your changes may be lost in future updates.'
				val: '此操作可在 WordPress 仪表盘中直接编辑您的插件。不建议直接编辑插件，直接编辑插件可能会引入不兼容的更改而使站点故障，且您的修改可能会在未来的更新中丢失。'
			},
			rt.ArrayItem{
				key: 'WordPress is not notifying any <a href="%1$s">Update Services</a> because of your site&#8217;s <a href="%2$s">visibility settings</a>.'
				val: '基于您站点的<a href="%2$s">可见性设置</a>，WordPress 不会通知任何<a href="%1$s">更新服务</a>。'
			},
			rt.ArrayItem{
				key: '<strong>Error:</strong> The root directory of your site is not <a href="%1$s">writable</a>, so creating a file automatically was not possible. This is the URL rewrite rule you should have in your %2$s file. Create a new file called %2$s in the root directory of your site. Click in the field and press %3$s (or %4$s on Mac) to select all. Then insert this code into the %2$s file.'
				val: '<strong>错误：</strong>您站点的根目录无法<a href="%1$s">写入</a>，因此无法自动创建文件。 这是 %2$s 文件中所需的 URL 重写规则。 请在站点根目录中创建一个名为 %2$s 的新文件。 单击该字段并按下 %3$s（Mac 请按下 %4$s）进行全选。 然后将此代码插入到 %2$s 文件中。'
			},
			rt.ArrayItem{
				key: 'Enter the same address here unless you <a href="%s">want your site home page to be different from your WordPress installation directory</a>.'
				val: '如果您想<a href="%s">让您的站点主页与 WordPress 安装目录不同</a>，请在此输入地址。'
			},
