			rt.ArrayItem{ key: 'Plugin Installation', val: '安装插件' },
			rt.ArrayItem{
				key: '<strong>Settings</strong> &mdash; This page shows a list of all settings associated with this site. Some are created by WordPress and others are created by plugins you activate. Note that some fields are grayed out and say Serialized Data. You cannot modify these values due to the way the setting is stored in the database.'
				val: '<strong>设置</strong>——这个页面显示了本站点关联的所有设置。其中一些由 WordPress 创建，另一些由您启用的插件创建。有一些字段显示为灰色的「序列化数据」，因为这些字段在数据库中的存储方式特殊，您不能修改这些字段。'
			},
			rt.ArrayItem{
				key: '<strong>Themes</strong> &mdash; This area shows themes that are not already enabled across the network. Enabling a theme in this menu makes it accessible to this site. It does not activate the theme, but allows it to show in the site&#8217;s Appearance menu. To enable a theme for the entire network, see the <a href="%s">Network Themes</a> screen.'
				val: '<strong>主题</strong>——此区域显示了还未在整个站点网络中启用的主题。在此启用主题将使其对本站点可用。这并不会启用主题，但会让主题在本站点的「外观」菜单中显示。要为整个站点网络启用主题，请查看<a href="%s">站点网络主题</a>页面。'
			},
			rt.ArrayItem{
				key: '<strong>Users</strong> &mdash; This displays the users associated with this site. You can also change their role, reset their password, or remove them from the site. Removing the user from the site does not remove the user from the network.'
				val: '<strong>用户</strong>——这里显示该站点所关联的用户。您也可以修改他们的角色、重置密码或将他们从站点移除。从站点中移除用户并不会将用户从站点网络中移除。'
			},
			rt.ArrayItem{
				key: '<strong>Info</strong> &mdash; The site URL is rarely edited as this can cause the site to not work properly. The Registered date and Last Updated date are displayed. Network admins can mark a site as archived, spam, deleted and mature, to remove from public listings or disable.'
				val: '<strong>信息</strong>——您不应经常编辑站点 URL，这可能让您的站点停止正常工作。注册日期和最后更新日期在这里显示。站点管理员可以将一个站点标记为已存档、垃圾、已删除或成人内容，也可以将站点从公开列表中移除或禁用站点。'
			},
			rt.ArrayItem{
				key: 'The menu is for editing information specific to individual sites, particularly if the admin area of a site is unavailable.'
				val: '此菜单用来编辑只适用于单个站点的信息，尤其是当该站点的管理区域不可用时。'
