			rt.ArrayItem{
				key: 'You can find new plugins to install by searching or browsing the directory right here in your own Plugins section.'
				val: '您可以在「安装插件」界面通过搜索或浏览目录来寻找并安装新插件。'
			},
			rt.ArrayItem{
				key: 'Plugins hook into WordPress to extend its functionality with custom features. Plugins are developed independently from the core WordPress application by thousands of developers all over the world. All plugins in the official <a href="%s">WordPress Plugin Directory</a> are compatible with the license WordPress uses.'
				val: '插件利用 WordPress 的钩子机制来扩展 WordPress 的功能，同时与 WordPress 核心应用程序相对独立。它们是由全球各地数以千计的开发者开发的。所有在官方 <a href="%s">WordPress.org 插件目录</a> 中的插件都与 WordPress 所用的许可证相兼容。'
			},
