			rt.ArrayItem{
				key: 'Trackbacks are a way to notify legacy blog systems that you&#8217;ve linked to them. If you link other WordPress sites, they&#8217;ll be notified automatically using <a href="%s">pingbacks</a>, no other action necessary.'
				val: 'Trackback 是一种通知老旧博客系统您链接到了他们的方法。如果您链接到了其他 WordPress 站点，将自动通过 <a href="%s">Pingback</a> 通知他们，无须其他操作。'
