			},
			rt.ArrayItem{
				key: 'The Code mode allows you to enter HTML along with your post text. Note that &lt;p&gt; and &lt;br&gt; tags are converted to line breaks when switching to the Code editor to make it less cluttered. When you type, a single line break can be used instead of typing &lt;br&gt;, and two line breaks instead of paragraph tags. The line breaks are converted back to tags automatically.'
				val: '代码模式使您可以向您的文章中加入 HTML。请注意，为了让编辑器更简洁，在切换到代码模式时，&lt;p&gt;和&lt;br&gt;标签会自动被转换为换行。在您打字时，您可以使用一个换行来代替&lt;br&gt;标签，使用两个换行来代替&lt;p&gt;标签。在切换回可视化模式后，这些换行将自动被转换为对应的标签。'
