			},
			rt.ArrayItem{
				key: "Howdy ###USERNAME###,\n\nYou recently clicked the 'Delete Site' link on your site and filled in a\nform on that page.\n\nIf you really want to delete your site, click the link below. You will not\nbe asked to confirm again so only click this link if you are absolutely certain:\n###URL_DELETE###\n\nIf you delete your site, please consider opening a new site here some time in\nthe future! (But remember that your current site and username are gone forever.)\n\nThank you for using the site,\nAll at ###SITENAME###\n###SITEURL###"
				val: '您好，###USERNAME###：\n\n您最近在您的站点上点击了「删除站点」链接，并填写了页面上的表单。\n\n若您确实想要删除站点，请点击以下链接。您将不会被要求再次确认，故请只在十分确定后再点击：\n###URL_DELETE###\n\n若您选择了删除站点，请考虑未来在这里重新开设一个新站点（但请记住，您现有的站点及用户名将一去不返）！\n\n祝好，\n###SITENAME### 敬上\n###SITEURL###'
			},
