			rt.ArrayItem{ key: 'Site Upload Space Quota', val: '站点更新空间限额' },
			rt.ArrayItem{ key: 'UPDATE LOG\n==========', val: '升级日志\n========' },
			rt.ArrayItem{
				key: "BETA TESTING?\n=============\n\nThis debugging email is sent when you are using a development version of WordPress.\n\nIf you think these failures might be due to a bug in WordPress, could you report it?\n * Open a thread in the support forums: https://wordpress.org/support/forum/alphabeta\n * Or, if you're comfortable writing a bug report: https://core.trac.wordpress.org/\n\nThanks! -- The WordPress Team"
				val: 'BETA 测试？\n==========\n\n这封调试邮件是在您使用开发版本的 WordPress 时发送给您的。\n\n如果您认为这些失败是由 WordPress 的 Bug 引起的，能请您报告给我们吗？\n * 在支持论坛中发表主题：https://wordpress.org/support/forum/alphabeta\n * 或者，如果您善于撰写 bug 报告：https://core.trac.wordpress.org/\n\n谢谢！——WordPress 团队'
