				val: '您的新 WordPress 站点已被成功建立：\n\n%1$s\n\n您可以用以下信息登录管理员账户：\n\n用户名：%2$s\n密码：%3$s\n在此登录：%4$s\n\n我们希望您喜欢您的新站点。谢谢！\n\n——WordPress 团队\nhttps://wordpress.org/\n'
