			},
			rt.ArrayItem{ key: 'Release Lead', val: '版本发布负责人' },
			rt.ArrayItem{
				key: 'Use the arrow buttons at the top of the dialog, or the left and right arrow keys on your keyboard, to navigate between media items quickly.'
				val: '使用对话框顶部的箭头按钮或键盘上的左右键，便能快速浏览媒体项目。'
