				val: '点选一个项目将会带出「附件详情」对话框，您可在其中预览媒体并快速做出修改。您在「附件详情」对话框中做出的所有修改都会自动保存。'
			},
			rt.ArrayItem{
				key: 'You can view your media in a simple visual grid or a list with columns. Switch between these views using the icons to the left above the media.'
				val: '您可以简单的网格视图或列表视图两种方式来查阅您的媒体文件。您可以使用媒体文件列表左上侧的图标来切换这些视图。'
			},
			rt.ArrayItem{
				key: 'All the files you&#8217;ve uploaded are listed in the Media Library, with the most recent uploads listed first.'
				val: '您上传的所有文件都在「媒体库」界面中按上传时间顺序列出，最新上传的显示在最前面。'
			},
			rt.ArrayItem{
				key: 'If you just want to get an idea of what&#8217;s available, you can browse Featured and Popular plugins by using the links above the plugins list. These sections rotate regularly.'
				val: '若您只想知道有什么插件可以选择，您可从列表上方的「特色」、「热门」中浏览。这些内容定期更新。'
