			rt.ArrayItem{ key: '%s failed to embed.', val: '嵌入 %s 失败。' },
			rt.ArrayItem{ key: 'Filtering by:', val: '筛选条件：' },
			rt.ArrayItem{ key: 'Displayed on attachment pages.', val: '在附件页显示。' },
			rt.ArrayItem{
				key: 'You can edit the image while preserving the thumbnail. For example, you may wish to have a square thumbnail that displays just a section of the image.'
				val: '您可以编辑图片，并不会影响缩略图。比如，您可能希望有一张只展示图片一部分的方形缩略图。'
			},
			rt.ArrayItem{
				key: 'Once you have made your selection, you can adjust it by entering the size in pixels. The minimum selection size is the thumbnail size as set in the Media settings.'
				val: '您做出选择后，选区大小可以通过输入像素值来调整。最小值为媒体设置中指定的缩略图大小。'
			},
			rt.ArrayItem{
