				val: '如何处理该用户名下的内容？'
			},
			rt.ArrayItem{
				key: '<strong>Delete</strong> brings you to the Delete Users screen for confirmation, where you can permanently remove a user from your site and delete their content. You can also delete multiple users at once by using bulk actions.'
				val: '「<strong>删除</strong>」链接会带您到「删除用户」确认页面。在确认页面，您可以永久从站点中删除用户，并决定是否保留他们的内容。您也可以通过批量操作功能一次删除多个用户。'
			},
			rt.ArrayItem{
				key: '<strong>Remove</strong> allows you to remove a user from your site. It does not delete their content. You can also remove multiple users at once by using bulk actions.'
				val: '点击「<strong>移除</strong>」可以将用户从您的站点中移除。该操作不会删除用户之前所发布的内容。您也可以通过批量操作功能一次移除多个用户。'
			},
			rt.ArrayItem{ key: 'themeDetails &amp; Preview', val: '详情及预览' },
			rt.ArrayItem{ key: 'Search Themes', val: '搜索主题' },
			rt.ArrayItem{ key: 'Add Themes', val: '安装主题' },
			rt.ArrayItem{
				key: 'https://wordpress.org/support/forum/how-to-and-troubleshooting'
				val: 'https://cn.wordpress.org/support/forum/issues/'
			},
			rt.ArrayItem{
				key: '<strong>At a Glance</strong> &mdash; Displays a summary of the content on your site and identifies which theme and version of WordPress you are using.'
				val: '<strong>概览</strong>——显示您站点上的内容概况，以及主题与 WordPress 程序的版本信息。'
			},
			rt.ArrayItem{
				key: '<strong>Box Controls</strong> &mdash; Click the title bar of the box to expand or collapse it. Some boxes added by plugins may have configurable content, and will show a &#8220;Configure&#8221; link in the title bar if you hover over it.'
				val: '<strong>管理模块</strong>——点击模块的标题栏即可展开或收起它。另外，有些模块提供额外的配置选项，在您将鼠标移动到这些模块的标题栏上方时，会出现「配置」链接。'
			},
			rt.ArrayItem{
				key: 'Sorry, you are not allowed to resume this theme.'
				val: '抱歉，您不能恢复此主题。'
			},
			rt.ArrayItem{ key: 'Edit date and time', val: '编辑日期和时间' },
			rt.ArrayItem{ key: 'Browse revisions', val: '浏览修订版本' },
			rt.ArrayItem{ key: 'Edit visibility', val: '编辑可见性' },
			rt.ArrayItem{ key: 'Edit status', val: '编辑状态' },
			rt.ArrayItem{
				key: '<a href="https://wordpress.org/support/forum/multisite/">Support forums</a>'
				val: '<a href="https://cn.wordpress.org/support/forum/issues/multisite/">支持论坛</a>'
			},
			rt.ArrayItem{
				key: 'Thank you for creating with <a href="%s">WordPress</a>.'
				val: '感谢使用 <a href="%s">WordPress</a> 进行创作。'
			},
			rt.ArrayItem{
				key: '<strong>Translations</strong> &mdash; The files translating WordPress into your language are updated for you whenever any other updates occur. But if these files are out of date, you can <strong>click the &#8220;Update Translations&#8221;</strong> button.'
				val: '<strong>翻译</strong>——包含 WordPress 翻译的文件将在任何其他升级执行时一并被升级。如果这些文件已过时，您可以<strong>点击「更新翻译」</strong>按钮。'
			},
			rt.ArrayItem{
				key: 'In most cases, WordPress will automatically apply maintenance and security updates in the background for you.'
				val: '在大多数情况下，WordPress 会在后台自动为您应用维护和安全更新。'
			},
			rt.ArrayItem{
				key: '<strong>WordPress</strong> &mdash; Updating your WordPress installation is a simple one-click procedure: just <strong>click on the &#8220;Update now&#8221; button</strong> when you are notified that a new version is available.'
				val: '<strong>WordPress</strong>——更新 WordPress 只需轻点一次鼠标。当有新版本可用时，<strong>点击「立即更新」按钮</strong>。'
			},
			rt.ArrayItem{
				key: 'If an update is available, you&#8127;ll see a notification appear in the Toolbar and navigation menu.'
				val: '如果更新可用，您将会在工具栏和导航菜单处看到通知。'
			},
			rt.ArrayItem{
				key: '<strong>Themes and Plugins</strong> &mdash; To update individual themes or plugins from this screen, use the checkboxes to make your selection, then <strong>click on the appropriate &#8220;Update&#8221; button</strong>. To update all of your themes or plugins at once, you can check the box at the top of the section to select all before clicking the update button.'
				val: '<strong>主题和插件</strong>——要在本页面更新主题和插件，使用复选框选择要升级的项目，并<strong>点击对应的「更新」</strong>。选择「主题」区域和「插件」区域最上方的复选框以全选。'
			},
			rt.ArrayItem{
				key: 'If you would like to see more themes to choose from, click on the &#8220;Add Theme&#8221; button and you will be able to browse or search for additional themes from the <a href="%s">WordPress Theme Directory</a>. Themes in the WordPress Theme Directory are designed and developed by third parties, and are compatible with the license WordPress uses. Oh, and they are free!'
				val: '如果您想查看更多可供选择的主题，请点击「安装主题」按钮，您就可以从<a href="%s">WordPress.org 主题目录</a>中浏览或搜索更多主题。 WordPress 主题目录中的主题是由第三方设计开发的，且与 WordPress 所用的版权许可证相兼容。最棒的是，它们都是免费的！'
			},
			rt.ArrayItem{
				key: '%1$s MB (%2$s%%) Space Used'
				val: '已使用 %1$s MB（%2$s%%）存储空间'
			},
			rt.ArrayItem{ key: '%s MB Space Allowed', val: '允许使用 %s MB 存储空间' },
			rt.ArrayItem{ key: 'M jS', val: 'n 月 j 日' },
			rt.ArrayItem{
				key: 'When this setting is in effect, a reminder is shown in the At a Glance box of the Dashboard that says, &#8220;Search engines discouraged&#8221;, to remind you that you have directed search engines to not crawl your site.'
				val: '当该项设置生效时，仪表盘中的「概况」模块将提醒您「自动建议搜索引擎不抓取」。您的站点在屏蔽搜索引擎期间无法被搜索引擎收录。'
			},
			rt.ArrayItem{ key: 'At a Glance', val: '概览' },
			rt.ArrayItem{ key: 'themeActive:', val: '已启用：' },
			rt.ArrayItem{ key: 'Accessibility Ready', val: '无障碍友好' },
			rt.ArrayItem{ key: 'This is a child theme of %s.', val: '这是 %s 的子主题。' },
			rt.ArrayItem{
				key: 'When previewing on smaller monitors, you can use the collapse icon at the bottom of the left-hand pane. This will hide the pane, giving you more room to preview your site in the new theme. To bring the pane back, click on the collapse icon again.'
				val: '在小屏幕设备上预览时，您可点击左下方的「隐藏控制区」图标，便可收起边栏，以便留出更多空间显示新主题的外观。再次点击该图标，边栏将展开。'
			},
			rt.ArrayItem{
				key: 'The theme being previewed is fully interactive &mdash; navigate to different pages to see how the theme handles posts, archives, and other page templates. The settings may differ depending on what theme features the theme being previewed supports. To accept the new settings and activate the theme all in one step, click the Activate &amp; Publish button above the menu.'
				val: '当前预览的主题是可互动的——您可以点击不同的页面来查看主题如何显示文章、存档和其他页面模板。根据主题所支持功能不同，您可以调整的项目也不同。要应用您在实时预览界面的设置，请点击左上角的「启用并发布」按钮。'
			},
			rt.ArrayItem{
				key: 'Tap or hover on any theme then click the Live Preview button to see a live preview of that theme and change theme options in a separate, full-screen view. You can also find a Live Preview button at the bottom of the theme details screen. Any installed theme can be previewed and customized in this way.'
				val: '轻触或悬浮在任何已安装的主题上，然后点击下方的「实时预览」链接来查看实时预览，并在单独的界面预览并调整主题设置。您也可在主题详情界面的最底找到「实时预览」按钮。任何已安装的主题都可通过此方式预览及自定义。'
			},
			rt.ArrayItem{
				key: 'The active theme is displayed highlighted as the first theme.'
				val: '当前主题作为第一个主题高亮显示。'
			},
			rt.ArrayItem{
				key: 'Click Customize for the active theme or Live Preview for any other theme to see a live preview'
				val: '点击当前主题的自定义按钮或其他主题的实时预览按钮来查看实时预览'
			},
			rt.ArrayItem{
				key: 'Click on the theme to see the theme name, version, author, description, tags, and the Delete link'
				val: '点击主题以查看主题名称、版本、作者、说明、标签和删除链接'
			},
			rt.ArrayItem{
				key: 'Hover or tap to see Activate and Live Preview buttons'
				val: '轻触或将鼠标放在已安装的主题上，便会显示「启用」及「实时预览」按钮'
			},
			rt.ArrayItem{
				key: 'This screen is used for managing your installed themes. Aside from the default theme(s) included with your WordPress installation, themes are designed and developed by third parties.'
				val: '此界面用于管理您已安装的主题。除了 WordPress 自带的默认主题之外，其他主题均是由第三方设计及开发的。'
			},
			rt.ArrayItem{
				key: 'To activate a widget drag it to a sidebar or click on it. To deactivate a widget and delete its settings, drag it back.'
				val: '要启用某一小工具，将它拖动到侧栏或点击它。要禁用某一小工具并删除其设置，将它拖回来。'
			},
			rt.ArrayItem{ key: '%s rating', val: '%s 个评级' },
			rt.ArrayItem{
				key: '%1$s rating based on %2$s rating'
				val: '%1$s 星（基于 %2$s 个评级）'
			},
			rt.ArrayItem{
				key: 'This screen shows an individual user all of their sites in this network, and also allows that user to set a primary site. They can use the links under each site to visit either the front end or the dashboard for that site.'
				val: '本页面向用户展示他们在本站点网络中拥有的全部站点。用户可以设置一个主站点。用户可以使用站点名称下方的链接来访问站点的前端或仪表盘。'
			},
			rt.ArrayItem{ key: 'Error: [%1$s] %2$s', val: '错误：[%1$s] %2$s' },
			rt.ArrayItem{ key: 'Rollback Error: [%1$s] %2$s', val: '回滚错误：[%1$s] %2$s' },
