			rt.ArrayItem{ key: 'Update Available', val: '更新可用' },
			rt.ArrayItem{
				key: "Are you sure you want to delete this theme?\n\nClick 'Cancel' to go back, 'OK' to confirm the delete."
				val: '您确认删除此主题吗？\n\n点击「取消」放弃，点击「确定」删除。'
