			rt.ArrayItem{
				key: 'Unable to submit this form, please refresh and try again.'
				val: '无法提交此表单，请刷新并重试。'
			},
			rt.ArrayItem{
				key: "<strong>Quick Draft</strong> &mdash; Allows you to create a new post and save it as a draft. Also displays links to the 3 most recent draft posts you've started."
				val: '<strong>快速草稿</strong>——让您创建新文章并保存为草稿，并显示 3 个指向最近草稿的链接。'
			},
			rt.ArrayItem{
				key: '<strong>Activity</strong> &mdash; Shows the upcoming scheduled posts, recently published posts, and the most recent comments on your posts and allows you to moderate them.'
				val: '<strong>动态</strong>——显示即将发布的计划文章、最新发布的文章以及您文章的最新评论，并让您对其进行审阅。'
			},
			rt.ArrayItem{
				key: '<strong>Screen Options</strong> &mdash; Use the Screen Options tab to choose which Dashboard boxes to show.'
				val: '<strong>显示选项</strong>——使用「显示选项」选项卡来选择要显示的仪表模块。'
