			rt.ArrayItem{ key: 'WordPress site: %s', val: 'WordPress 站点：%s' },
			rt.ArrayItem{
				key: 'Your site was running version %s.'
				val: '您的站点正在运行 %s 版本。'
			},
			rt.ArrayItem{
				key: 'Your site at %1$s experienced a critical failure while trying to update WordPress to version %2$s.'
				val: '您位于 %1$s 的站点在更新至到 WordPress %2$s 的过程中遇到了严重问题。'
			},
			rt.ArrayItem{
				key: 'WordPress %s is also now available.'
				val: 'WordPress %s 也已可用。'
			},
			rt.ArrayItem{
				key: 'The update cannot be installed because your site is unable to copy some files. This is usually due to inconsistent file permissions.'
				val: '因为不能复制一些文件，更新无法安装。这通常是因为存在不正确的文件权限。'
			},
			rt.ArrayItem{
				key: 'Your translations are all up to date.'
				val: '您的所有翻译均为最新版本。'
			},
			rt.ArrayItem{ key: 'Translations', val: '翻译' },
			rt.ArrayItem{ key: 'Error code: %s', val: '错误代码：%s' },
			rt.ArrayItem{
				key: 'Your hosting company, support forum volunteers, or a friendly developer may be able to use this information to help you:'
				val: '您的主机商、支持论坛的志愿者、或一位友善的开发者将可以利用以下信息来帮您：'
			},
			rt.ArrayItem{ key: 'The WordPress Team', val: 'WordPress 团队' },
			rt.ArrayItem{
				key: 'You also have some plugins or themes with updates available. Update them now:'
				val: '您的一些插件或主题也有更新可用，请更新它们：'
			},
			rt.ArrayItem{
				key: 'If you experience any issues or need support, the volunteers in the WordPress.org support forums may be able to help.'
				val: '如果您遇到了任何问题或需要帮助，WordPress.org 支持论坛的志愿者或许能帮到您。'
			},
			rt.ArrayItem{
				key: 'Keeping your site updated is important for security. It also makes the internet a safer place for you and your readers.'
				val: '保持更新站点对确保安全至关重要，这也会让互联网和您的读者更安全。'
			},
			rt.ArrayItem{
				key: "Please check out your site now. It's possible that everything is working. If it says you need to update, you should do so:"
				val: '请检查您的站点，有可能一切工作正常。如果它说您需要更新，请照做：'
			},
			rt.ArrayItem{
				key: "This means your site may be offline or broken. Don't panic; this can be fixed."
				val: '这意味着您的站点可能已不可用或损坏。别慌，这能被修好。'
			},
			rt.ArrayItem{
				key: 'Your site at %1$s experienced a critical failure while trying to update to the latest version of WordPress, %2$s.'
				val: '您位于 %1$s 的站点在更新至 WordPress 的最新版本，%2$s 的过程中遇到了严重问题。'
			},
			rt.ArrayItem{
				key: 'Updating is easy and only takes a few moments:'
				val: '升级很简单，花不了您多长时间：'
			},
			rt.ArrayItem{
				key: 'Please update your site at %1$s to WordPress %2$s.'
				val: '请升级您位于 %1$s 的站点到 WordPress %2$s。'
			},
			rt.ArrayItem{
				key: 'For more on version %s, see the About WordPress screen:'
				val: '详细了解 %s 版本，请参阅「关于 WordPress」页面：'
			},
			rt.ArrayItem{
				key: 'No further action is needed on your part.'
				val: '您不需要再做什么。'
			},
			rt.ArrayItem{
				key: 'Howdy! Your site at %1$s has been updated automatically to WordPress %2$s.'
				val: '您好！您的站点 %1$s 已被自动更新至 WordPress %2$s。'
			},
			rt.ArrayItem{
				key: '[%1$s] URGENT: Your site may be down due to a failed update'
				val: '[%1$s] 紧急：因更新失败，您的站点或已不可用'
			},
			rt.ArrayItem{
				key: '[%1$s] WordPress %2$s is available. Please update!'
				val: '[%1$s] WordPress %2$s 现已可用，请更新！'
			},
			rt.ArrayItem{
				key: '[%1$s] Your site has updated to WordPress %2$s'
				val: '[%1$s] 您的站点已被更新至 WordPress %2$s'
			},
			rt.ArrayItem{ key: 'Translations for %s', val: '%s 的翻译' },
			rt.ArrayItem{
				key: 'Updating translations for %1$s (%2$s)&#8230;'
				val: '正在更新 %1$s（%2$s）的翻译…'
			},
			rt.ArrayItem{ key: 'Update Translations', val: '更新翻译' },
			rt.ArrayItem{ key: 'Background updates', val: '后台更新' },
			rt.ArrayItem{
				key: 'There is not enough free disk space to complete the update.'
				val: '磁盘空间不足，无法执行更新。'
			},
			rt.ArrayItem{ key: 'Updating plugin: %s', val: '升级插件：%s' },
			rt.ArrayItem{ key: 'Updating theme: %s', val: '升级主题：%s' },
			rt.ArrayItem{ key: 'Translation updated successfully.', val: '翻译升级成功。' },
			rt.ArrayItem{ key: 'Translation update failed.', val: '翻译升级失败。' },
			rt.ArrayItem{
				key: 'Some of your translations need updating. Sit tight for a few more seconds while they are updated as well.'
				val: '一些翻译需要更新，请稍等。'
			},
			rt.ArrayItem{
				key: 'Create a brand new user and add them to this site.'
				val: '新建用户，并将用户加入此站点。'
			},
			rt.ArrayItem{
				key: 'Upgrading to a newer version of the same theme will override changes made here. To avoid this, consider creating a <a href="%s">child theme</a> instead.'
				val: '升级新版本的主题将会导致您所做的修改被覆盖。要避免类似悲剧的发生，请考虑创建一个<a href="%s">子主题</a>。'
			},
			rt.ArrayItem{
				key: 'The sizes listed below determine the maximum dimensions in pixels to use when adding an image to the Media Library.'
				val: '下面列出来的尺寸决定插入媒体库内的图片之最大尺寸。以像素为单位。'
			},
			rt.ArrayItem{
				key: 'Comment must be manually approved'
				val: '评论必须经人工批准'
			},
			rt.ArrayItem{
				key: '<strong>Clicking the arrow to the right of any menu item</strong> in the editor will reveal a standard group of settings. Additional settings such as link target, CSS classes, link relationships, and link descriptions can be enabled and disabled via the Screen Options tab.'
				val: '在编辑器中<strong>点击任一菜单项目标题右侧的箭头</strong>会显示一组标准设置。附加设置（如链接目标、 CSS 类、链接关系和链接描述等）可在「显示选项」页中设置显示或隐藏。'
			},
			rt.ArrayItem{
				key: 'Menus can be displayed in locations defined by your theme, even used in sidebars by adding a &#8220;Navigation Menu&#8221; widget on the <a href="%1$s">Widgets</a> screen. If your theme does not support the navigation menus feature (the default themes, %2$s and %3$s, do), you can learn about adding this support by following the documentation link to the side.'
				val: '菜单可在您的主题指定的位置显示，或通过<a href="%1$s">小工具</a>中的「导航菜单」小工具显示在侧边栏中。如果您的主题不支持导航菜单功能（默认主题 %2$s 和 %3$s 均支持），您可以查阅侧边的文档链接了解如何加入这一支持。'
			},
