				val: '在更换主题时，边栏的数量通常各不相同，有时这些冲突会给更换主题的过程带来一些小麻烦。如果您更换主题后发现边栏小工具缺失，请看看本页面下方的「未启用」区域，您的小工具及其设置将会被保存在那里。'
			},
			rt.ArrayItem{
				key: '<strong>Parent</strong> &mdash; Categories, unlike tags, can have a hierarchy. You might have a Jazz category, and under that have child categories for Bebop and Big Band. Totally optional. To create a subcategory, just choose another category from the Parent dropdown.'
				val: '<strong>父极分类</strong>与标签不同，它可以有层级结构。您可以有一个名为「音乐」的分类，在该分类下可以有名为「流行」和「古典」的子分类（完全可选）。要创建子分类，只需从父级分类下拉菜单中选择一个分类即可。'
			},
			rt.ArrayItem{
