			rt.ArrayItem{
				key: 'The title field and the big Post Editing Area are fixed in place, but you can reposition all the other boxes using drag and drop. You can also minimize or expand them by clicking the title bar of each box. Use the Screen Options tab to unhide more boxes (Excerpt, Send Trackbacks, Custom Fields, Discussion, Slug, Author) or to choose a 1- or 2-column layout for this screen.'
				val: '标题区域和文章编辑区域的位置是固定的，但您可以通过拖拽功能重新排列其他所有模块。点击模块标题可以最小化或展开模块。一些模块默认隐藏，您也可以在「显示选项」中取消隐藏这些模块（摘要、发送 Trackback 、自定义字段、讨论、别名、作者）。您还可以在单栏布局和双栏布局中切换。'
			},
			rt.ArrayItem{
				key: 'Do not forget to click &#8220;Save Changes&#8221; when you are done!'
				val: '完成时不要忘记点击「保存更改」！'
			},
			rt.ArrayItem{
				key: 'To use a background image, simply upload it or choose an image that has already been uploaded to your Media Library by clicking the &#8220;Choose Image&#8221; button. You can display a single instance of your image, or tile it to fill the screen. You can have your background fixed in place, so your site content moves on top of it, or you can have it scroll with your site.'
				val: '要使用背景图片，您需先上传，或从媒体库中已上传过的图片中选择。您可选择令其单次显示，或平铺多次以充满屏幕。您还可以使背景固定不动，站点的内容在其上滚动。也可让背景与站点内容同步滚动。'
			},
			rt.ArrayItem{ key: 'media itemEdit', val: '编辑' },
			rt.ArrayItem{ key: 'colorDefault: %s', val: '默认色：%s' },
			rt.ArrayItem{ key: 'column nameUploaded to', val: '上传至' },
			rt.ArrayItem{
				key: 'The uploaded file is not a valid image. Please try again.'
				val: '上传的文件不是有效的图片。请重试。'
			},
			rt.ArrayItem{ key: 'Choose a Custom Header', val: '选择自定义页眉' },
			rt.ArrayItem{ key: 'Choose a Background Image', val: '选择背景图片' },
			rt.ArrayItem{
				key: 'In the Header Text section of this page, you can choose whether to display this text or hide it. You can also choose a color for the text by clicking the Select Color button and either typing in a legitimate HTML hex value, e.g. &#8220;#ff0000&#8221; for red, or by choosing a color using the color picker.'
				val: '在「顶部文本」一节，您可以选择是否显示这些文字。颜色可以通过点击「选择颜色」来使用选色器选择，或者手工输入 HTML 十六进制颜色代码（如红色「#ff0000」）。'
			},
			rt.ArrayItem{
				key: 'You can also choose a background color by clicking the Select Color button and either typing in a legitimate HTML hex value, e.g. &#8220;#ff0000&#8221; for red, or by choosing a color using the color picker.'
				val: '颜色可以通过点击「选择颜色」来使用选色器选择，或者手工输入 HTML 十六进制颜色代码（如红色「#ff0000」）。'
			},
			rt.ArrayItem{
				key: 'In the <strong>In response to</strong> column, there are three elements. The text is the name of the post that inspired the comment, and links to the post editor for that entry. The View Post link leads to that post on your live site. The small bubble with the number in it shows the number of approved comments that post has received. If there are pending comments, a red notification circle with the number of pending comments is displayed. Clicking the notification circle will filter the comments screen to show only pending comments on that post.'
				val: '在<strong>回复至</strong>一栏中，包含三项内容。文章标题代表评论发布于何处，并链接到该文章的编辑器界面。「查看文章」链接则可查看该文章在您的网站上的实时页面。带有数字的小气泡代表该文章收到的已批准评论的数量。如果有待处理的评论，则会显示一个含有待处理评论数量的红色圆圈。单击该圆圈，则将仅显示发表于该文章的待处理评论。'
			},
			rt.ArrayItem{ key: 'ID #%1$s: %2$s', val: 'ID #%1$s：%2$s' },
			rt.ArrayItem{
				key: 'ID #%1$s: %2$s <strong>The current user will not be deleted.</strong>'
				val: 'ID #%1$s：%2$s <strong>当前用户不会被删除。</strong>'
			},
			rt.ArrayItem{ key: 'Used: %1$s%% of %2$s', val: '已用：%2$s 中的 %1$s%%' },
			rt.ArrayItem{ key: 'Please select an option.', val: '请选择一个选项。' },
			rt.ArrayItem{
				key: 'After you&#8217;ve done that, click &#8220;Run the installation&#8221;.'
				val: '完成这些后，请点击「运行安装程序」。'
			},
			rt.ArrayItem{
				key: 'If you want to install a plugin that you&#8217;ve downloaded elsewhere, click the Upload Plugin button above the plugins list. You will be prompted to upload the .zip package, and once uploaded, you can activate the new plugin.'
				val: '如果您想安装从别处下载的插件，请点击列表上方的「上传」。 WordPress 接受 .zip 格式的压缩包，在上传成功后，您就可以启用该插件了。'
			},
			rt.ArrayItem{
				key: 'You can also browse a user&#8217;s favorite plugins, by using the Favorites link above the plugins list and entering their WordPress.org username.'
				val: '您也可以浏览他人收藏的插件。点击列表上方的「收藏」链接，然后输入一个用户名。'
			},
			rt.ArrayItem{
				key: 'If you know what you are looking for, Search is your best bet. The Search screen has options to search the WordPress Plugin Directory for a particular Term, Author, or Tag. You can also search the directory by selecting popular tags. Tags in larger type mean more plugins have been labeled with that tag.'
				val: '若您知道您需要何种插件，可以使用搜索功能，搜索界面的选项可对 WordPress 插件目录中的特定字词、作者或标签进行搜索。 您也可以通过选择热门标签来搜索目录，字体较大的标签意味着有更多的插件使用了该标签。'
			},
			rt.ArrayItem{
				key: 'It is up to search engines to honor this request.'
				val: '搜索引擎将本着自觉自愿的原则对待 WordPress 提出的请求。并不是所有搜索引擎都会遵守这类请求。'
			},
			rt.ArrayItem{
				key: 'Discourage search engines from indexing this site'
				val: '建议搜索引擎不索引本站点'
			},
			rt.ArrayItem{
				key: 'Allow search engines to index this site'
				val: '允许搜索引擎索引本站点'
			},
			rt.ArrayItem{ key: 'Search engine visibility', val: '对搜索引擎的可见性' },
			rt.ArrayItem{
				key: 'Welcome to WordPress %1$s. You will be redirected to the About WordPress screen. If not, click <a href="%2$s">here</a>.'
				val: '欢迎使用 WordPress %1$s。我们将带您到「关于 WordPress」页面。如果没有自动跳转，请<a href="%2$s">点击这里</a>。'
			},
			rt.ArrayItem{ key: 'Get Favorites', val: '获取收藏列表' },
			rt.ArrayItem{
				key: 'Your WordPress.org username:'
				val: '您的 WordPress.org 用户名：'
			},
			rt.ArrayItem{
				key: 'If you have marked plugins as favorites on WordPress.org, you can browse them here.'
				val: '您可在此浏览在 WordPress.org 上收藏的插件。'
			},
			rt.ArrayItem{ key: 'Welcome to WordPress!', val: '欢迎使用 WordPress！' },
			rt.ArrayItem{
				key: 'Search engines discouraged'
				val: '自动建议搜索引擎不抓取'
			},
			rt.ArrayItem{
				key: 'This <a href="%1$s">child theme</a> requires its parent theme, %2$s.'
				val: '这个<a href="%1$s">子主题</a>需要其父主题 %2$s 才能工作。'
			},
			rt.ArrayItem{ key: 'Plugin InstallerFavorites', val: '收藏' },
			rt.ArrayItem{
				key: 'To install the theme so you can preview it with your site&#8217;s content and customize its theme options, click the "Install" button at the top of the left-hand pane. The theme files will be downloaded to your website automatically. When this is complete, the theme is now available for activation, which you can do by clicking the "Activate" link, or by navigating to your Manage Themes screen and clicking the "Live Preview" link under any installed theme&#8217;s thumbnail image.'
				val: '点击左上角「安装」按钮安装主题之后，方可使用「实时预览」功能进行主题自定义。安装后主题文件将被自动下载至您的站点。完成后，您可以使用「启用」链接直接启用主题，或转到「已安装的主题」页面，点击「实时预览」按钮来自定义并预览。'
			},
			rt.ArrayItem{ key: 'widgetAdd', val: '添加' },
			rt.ArrayItem{ key: 'widgetEdit', val: '编辑' },
			rt.ArrayItem{ key: 'Search by tag', val: '根据标签查找' },
			rt.ArrayItem{ key: 'Search by author', val: '根据作者查找' },
			rt.ArrayItem{ key: 'Search by keyword', val: '根据关键词查找' },
			rt.ArrayItem{ key: 'Type of search', val: '搜索类型' },
			rt.ArrayItem{ key: 'Screen Options Tab', val: '「显示选项」选项卡' },
			rt.ArrayItem{ key: 'Contextual Help Tab', val: '「上下文帮助」选项卡' },
			rt.ArrayItem{ key: 'Select comment', val: '选择评论' },
			rt.ArrayItem{
				key: 'Tags can be selectively converted to categories using the <a href="%s">tag to category converter</a>.'
				val: '标签可以选择性地转换成分类，请使用<a href="%s">分类与标签转换器</a>。'
			},
			rt.ArrayItem{
				key: 'You can delete Link Categories in the Bulk Action pull-down, but that action does not delete the links within the category. Instead, it moves them to the default Link Category.'
				val: '您可以通过「批量操作」来一次删除多个链接分类，但是删除操作并不影响分类中的链接。其下链接将被自动移至默认的链接分类。'
			},
			rt.ArrayItem{
				key: 'Creating a Page is very similar to creating a Post, and the screens can be customized in the same way using drag and drop, the Screen Options tab, and expanding/collapsing boxes as you choose. This screen also has the distraction-free writing space, available in both the Visual and Code modes via the Fullscreen buttons. The Page editor mostly works the same as the Post editor, but there are some Page-specific features in the Page Attributes box.'
				val: '创建页面与创建文章非常类似，并且可以使用拖放、屏幕选项选项卡和展开/折叠模块以相同的方式自定义屏幕。该界面还拥有免打扰写作模式，可通过全屏按钮在可视化模式和代码模式下使用。页面编辑器的工作方式与文章编辑器大致相同，但页面属性框中有一些特定于页面的功能。'
			},
			rt.ArrayItem{
				key: 'You can select an image to be shown at the top of your site by uploading from your computer or choosing from your media library. After selecting an image you will be able to crop it.'
				val: '在这里，您可以上传新图片或从媒体库中已上传的图片中选择，以取代默认的图片。上传完成后，您将可以按喜好自己剪裁图片。'
			},
			rt.ArrayItem{ key: 'Skip to main content', val: '跳至主内容' },
			rt.ArrayItem{
				key: 'You can set a custom image header for your site. Simply upload the image and crop it, and the new header will go live immediately. Alternatively, you can use an image that has already been uploaded to your Media Library by clicking the &#8220;Choose Image&#8221; button.'
				val: '您可为站点选择一个自定义页眉图片。只需上传需要的图片并进行剪裁，新的页眉图片将会立即生效。或者您也可以点击「选择图片」，使用「媒体库」中原来上传过的图片。'
			},
			rt.ArrayItem{ key: 'Skip Cropping, Publish Image as Is', val: '不剪裁以原样发布' },
			rt.ArrayItem{ key: 'Choose Image', val: '选择图片' },
			rt.ArrayItem{
				key: 'Or choose an image from your media library:'
				val: '或从您的媒体库中选择图片：'
			},
			rt.ArrayItem{ key: 'Select Image', val: '选择图片' },
			rt.ArrayItem{
				key: 'If you do not want a header image to be displayed on your site at all, click the &#8220;Remove Header Image&#8221; button at the bottom of the Header Image section of this page. If you want to re-enable the header image later, you just have to select one of the other image options and click &#8220;Save Changes&#8221;.'
				val: '如果您不想要页眉图片，点击本页下方「页眉图片」一节的「移除页眉图片」按钮。移除之后如需再次启用页眉图片功能，您只须选择一张图片，然后点击「保存更改」。'
			},
			rt.ArrayItem{ key: 'pluginInstalled', val: '已安装' },
			rt.ArrayItem{ key: 'Previewing and Customizing', val: '预览和自定义' },
			rt.ArrayItem{ key: 'Previewing and Installing', val: '预览并安装' },
			rt.ArrayItem{
				key: 'Once you have generated a list of themes, you can preview and install any of them. Click on the thumbnail of the theme you are interested in previewing. It will open up in a full-screen Preview page to give you a better idea of how that theme will look.'
				val: '生成主题列表后，您可以预览或是安装任何一个主题。 单击您有兴趣预览的主题缩略图，主题将在全屏预览页面中打开，让您更直观地了解该主题的外观。'
			},
			rt.ArrayItem{
				key: 'You are using the browser&#8217;s built-in file uploader. The WordPress uploader includes multiple file selection and drag and drop capability. <button %s>Switch to the multi-file uploader</button>.'
				val: '您正在使用浏览器的内置文件上传器。WordPress 上传器支持多文件选择和拖放功能。<button %s>切换到多文件上传器</button>。'
			},
			rt.ArrayItem{
				key: 'The Categories and Tags Converter link on this screen will take you to the Import screen, where that Converter is one of the plugins you can install. Once that plugin is installed, the Activate Plugin &amp; Run Importer link will take you to a screen where you can choose to convert tags into categories or vice versa.'
				val: '本界面上的「分类与标签转换器」链接可将您带到「导入」界面，您可在该界面安装对应的转换器插件。安装完成后，点击「启用插件并运行导入工具」，您就可以进行分类和标签的双向转换了。'
			},
			rt.ArrayItem{
				key: 'Categories have hierarchy, meaning that you can nest sub-categories. Tags do not have hierarchy and cannot be nested. Sometimes people start out using one on their posts, then later realize that the other would work better for their content.'
				val: '分类之间可以有层级关系，您可以在一个分类下安排其他子分类。标签则没有层级关系，不可嵌套。有时候，人们刚开始写文章时，会先选择分类、标签其中之一来使用，然后发现另一种或许更加适合自己。'
			},
			rt.ArrayItem{
				key: 'For most themes, the header text is your Site Title and Tagline, as defined in the <a href="%s">General Settings</a> section.'
				val: '大多数主题的顶部文字显示的是「站点标题」和「副标题」。您可以在<a href="%s">常规选项</a>进行修改。'
			},
			rt.ArrayItem{
				key: 'If your theme has more than one default header image, or you have uploaded more than one custom header image, you have the option of having WordPress display a randomly different image on each page of your site. Click the &#8220;Random&#8221; radio button next to the Uploaded Images or Default Images section to enable this feature.'
				val: '如果您有多张页眉图片，您可以选择让 WordPress 每次随机展示其中一张图片。如需实现这种效果，勾选「已上传的图片」旁边的「随机」单选框。'
			},
			rt.ArrayItem{
				key: 'Some themes come with additional header images bundled. If you see multiple images displayed, select the one you would like and click the &#8220;Save Changes&#8221; button.'
				val: '一些主题附带了更多的页眉图片供您选择。若显示了多幅图片，请选择您喜爱的图片并点击「保存更改」按钮。'
			},
			rt.ArrayItem{
				key: 'You can choose from the theme&#8217;s default header images, or use one of your own. You can also customize how your Site Title and Tagline are displayed.'
				val: '您可以从主题默认的页眉图片中选择，或使用您自己准备的页眉图片。您还可以定义「站点标题」和「副标题」的显示方式。'
			},
			rt.ArrayItem{
				key: 'This screen is used to customize the header section of your theme.'
				val: '在本页面调整主题顶部的样式。'
			},
			rt.ArrayItem{ key: 'Configuration Error', val: '配置有误' },
			rt.ArrayItem{
				key: 'Revert to the <strong>Browser Uploader</strong> by clicking the link below the drag and drop box.'
				val: '点击拖拽框下方的链接可恢复使用<strong>浏览器上传工具</strong>。'
			},
			rt.ArrayItem{ key: 'User deleted.', val: '用户已删除。' },
			rt.ArrayItem{
				key: 'Could not copy files. You may have run out of disk space.'
				val: '无法复制文件，您可能用完了磁盘空间。'
			},
			rt.ArrayItem{
				key: 'Find a theme based on specific features.'
				val: '根据主题特性寻找主题。'
			},
			rt.ArrayItem{
				key: 'Search for themes by keyword.'
				val: '根据关键词搜索主题。'
			},
			rt.ArrayItem{
				key: 'In all likelihood, these items were supplied to you by your web host. If you do not have this information, then you will need to contact them before you can continue. If you are ready&hellip;'
				val: '通常，您的主机服务商会告诉您这些信息。如果您没有这些信息，在继续之前您将需要联系他们。如果您准备好了…'
