			},
			rt.ArrayItem{ key: 'Header Text', val: '顶部文本' },
			rt.ArrayItem{
				key: 'There is a new version of %1$s available. <a href="%2$s" %3$s>View version %4$s details</a> or <a href="%5$s" %6$s>update now</a>.'
				val: '%1$s 有新版本可用。<a href="%2$s" %3$s> 查看版本 %4$s 详情</a>或<a href="%5$s" %6$s>立即更新</a>。'
			},
			rt.ArrayItem{ key: 'By %s.', val: '作者「%s」' },
			rt.ArrayItem{ key: 'Add Comment', val: '添加评论' },
			rt.ArrayItem{ key: 'http://ma.tt/', val: 'http://ma.tt/' },
			rt.ArrayItem{
				key: 'This is not just a plugin, it symbolizes the hope and enthusiasm of an entire generation summed up in two words sung most famously by Louis Armstrong: Hello, Dolly. When activated you will randomly see a lyric from <cite>Hello, Dolly</cite> in the upper right of your admin screen on every page.'
				val: '这不是普通的插件，它象征着一代人希望和热情，浓缩成 Louis Armstrong 的四个字：你好，多莉。在启用后，在您站点后台每个页面的右上角都可以看到一句来自《俏红娘》音乐剧的英文原版台词。'
			},
			rt.ArrayItem{ key: 'Hello Dolly', val: '你好多莉' },
			rt.ArrayItem{
