				val: '%1$s 有新版本可用。<a href="%2$s" %3$s> 查看版本 %4$s 详情</a>。<em>自动更新对此主题不可用。</em>'
			},
			rt.ArrayItem{ key: 'HowdyWelcome', val: '欢迎' },
			rt.ArrayItem{ key: 'Delete My Site Permanently', val: '永久删除我的站点' },
			rt.ArrayItem{
				key: "I'm sure I want to permanently delete my site, and I am aware I can never get it back or use %s again."
				val: '我确定要永久删除我的站点，并且我了解我不能再将其恢复，同时我知晓我今后也将无法再使用 %s 了。'
			},
			rt.ArrayItem{
				key: 'Remember, once deleted your site cannot be restored.'
				val: '请注意，删除后数据不可恢复。'
			},
			rt.ArrayItem{
				key: 'If you do not want to use your %s site any more, you can delete it using the form below. When you click <strong>Delete My Site Permanently</strong> you will be sent an email with a link in it. Click on this link to delete your site.'
				val: '如果您不想再使用 %s 站点了，您可以通过下面的表单来删除它。当您点击<strong>「永久删除我的站点」</strong>之后，我们将发送一封确认邮件。请点击确认邮件中的链接来删除您的站点。'
			},
			rt.ArrayItem{
				key: 'Thank you. Please check your email for a link to confirm your action. Your site will not be deleted until this link is clicked.'
				val: '谢谢。请检查您收到的邮件来获得链接以确认此操作。您的站点在该链接被点击后才会被删除。'
