			rt.ArrayItem{ key: 'American English', val: '美式英语' },
			rt.ArrayItem{ key: 'View Site', val: '查看站点' },
			rt.ArrayItem{ key: 'Visit Dashboard', val: '访问「仪表盘」' },
			rt.ArrayItem{ key: 'Your Sites', val: '您的站点' },
			rt.ArrayItem{
