				val: '文件 %1$s 已经存在于 WordPress 的上级目录。如果您希望重置该文件中的任何配置项目，请先删除该文件。您可以<a href="%2$s">现在安装</a>。'
			},
			rt.ArrayItem{
				key: 'The file %1$s already exists. If you need to reset any of the configuration items in this file, please delete it first. You may try <a href="%2$s">installing now</a>.'
				val: '文件 %1$s 已经存在。如果您希望重置该文件中的任何配置项目，请先删除该文件。您可以<a href="%2$s">现在安装</a>。'
			},
			rt.ArrayItem{
				key: 'Sorry, I need a %s file to work from. Please re-upload this file to your WordPress installation.'
				val: '抱歉，我需要 %s 文件才能工作。请重新上传该文件到您的 WordPress。'
			},
			rt.ArrayItem{
				key: 'To allow use of this page to automatically repair database problems, please add the following line to your %s file. Once this line is added to your config, reload this page.'
				val: '要允许本页面自动修复数据库问题，请将下面一行加入您的 %s 文件。完成后请刷新本页面。'
			},
			rt.ArrayItem{ key: 'No comments awaiting moderation.', val: '尚无评论待审。' },
			rt.ArrayItem{ key: 'Plugin installer section titleOther Notes', val: '其他备注' },
			rt.ArrayItem{ key: 'Plugin installer section titleChangelog', val: '修订历史' },
			rt.ArrayItem{ key: 'Plugin installer section titleScreenshots', val: '截图' },
			rt.ArrayItem{ key: 'Plugin installer section titleFAQ', val: '常见问题' },
			rt.ArrayItem{ key: 'Plugin installer section titleInstallation', val: '安装' },
			rt.ArrayItem{ key: 'Plugin installer section titleDescription', val: '描述' },
			rt.ArrayItem{ key: 'Plugin Homepage &#187;', val: '插件主页 &#187;' },
			rt.ArrayItem{
				key: 'You can export a file of your site&#8217;s content in order to import it into another installation or platform. The export file will be an XML file format called WXR. Posts, pages, comments, custom fields, categories, and tags can be included. You can choose for the WXR file to include only certain posts or pages by setting the dropdown filters to limit the export by category, author, date range by month, or publishing status.'
				val: '您可以导出整个站点的内容，然后在另一个 WordPress 乃至其他平台的站点中导入。 WordPress 将导出一个 WXR 格式的 xml 文件，其中可储存文章、页面、评论、自定义字段、分类和标签。通过筛选，您可以只导出一部分内容，比如某个分类下的文章、某段时间的文章、某位作者的文章、某个状态的文章等。'
			},
			rt.ArrayItem{
				key: 'Failed to repair the %1$s table. Error: %2$s'
				val: '无法修复 %1$s 表。错误消息：%2$s'
			},
			rt.ArrayItem{
				key: 'New users will receive an email letting them know they&#8217;ve been added as a user for your site. This email will also contain their password. Check the box if you do not want the user to receive a welcome email.'
				val: '新用户将收到一封邮件，告知他们已被添加为您站点的用户。该邮件会包含用户密码。 如果您不希望用户收到欢迎邮件，请选中此框。'
			},
			rt.ArrayItem{
				key: "There are unsaved changes that will be lost. 'OK' to continue, 'Cancel' to return to the Image Editor."
				val: '未保存的更改将丢失。按「确定」以继续，按「取消」可返回「图片编辑器」。'
			},
			rt.ArrayItem{
				key: 'Post via email settings allow you to send your WordPress installation an email with the content of your post. You must set up a secret email account with POP3 access to use this, and any mail received at this address will be posted, so it&#8217;s a good idea to keep this address very secret.'
				val: '「通过邮件发布文章」 能让您以发送邮件方式，将邮件内容在 WordPress 网站发布为文章。您必须设置一个支持 POP3 通讯协议的秘密邮件帐户才能使用这项功能，该邮箱收到的任何邮件都会将其内容发布为网站文章，因此务必对这个邮箱地址严加保密。'
			},
			rt.ArrayItem{
				key: 'You can filter the list of users by User Role using the text links above the users list to show All, Administrator, Editor, Author, Contributor, or Subscriber. The default view is to show all users. Unused User Roles are not listed.'
				val: '您可以使用用户列表上方的文字链接按用户角色筛选用户列表，可显示所有、管理员、编辑、作者、贡献者或订阅者。默认视图为显示所有用户。未使用的用户角色不会被列出。'
			},
			rt.ArrayItem{
				key: 'In previous versions of WordPress, all importers were built-in. They have been turned into plugins since most people only use them once or infrequently.'
				val: '在先前的 WordPress 版本中，导入工具都是内建的。最近我们将导入工具全部移植成了插件，因为大部分用户不会经常使用它们。'
			},
			rt.ArrayItem{
				key: 'There is an autosave of this post that is more recent than the version below. <a href="%s">View the autosave</a>'
				val: '此文章存在比以下修订版本更新的自动保存。 <a href="%s">查看自动保存</a>'
			},
			rt.ArrayItem{
				key: 'Image could not be processed. Please go back and try again.'
				val: '无法处理图片。请返回重试。'
			},
			rt.ArrayItem{
				key: 'The active theme is broken. Reverting to the default theme.'
				val: '当前启用的主题已受损。自动切换回默认主题。'
			},
			rt.ArrayItem{
				key: 'WordPress can also attempt to optimize the database. This improves performance in some situations. Repairing and optimizing the database can take a long time and the database will be locked while optimizing.'
				val: 'WordPress 还可以尝试优化数据库，这在某些情况下能提高数据库性能。修复和优化数据库的过程需要一段时间，请耐心等待——在此期间我们会锁定数据表。'
			},
			rt.ArrayItem{
				key: 'WordPress can automatically look for some common database problems and repair them. Repairing can take a while, so please be patient.'
				val: 'WordPress 能自动检测并修复一些常见数据库问题。修复过程需要一段时间，请耐心等待。'
			},
			rt.ArrayItem{
				key: 'Repairs complete. Please remove the following line from wp-config.php to prevent this page from being used by unauthorized users.'
				val: '修复完成。请移除刚刚在「wp-config.php」中添加的那行代码，以防他人滥用本页面。'
			},
			rt.ArrayItem{
				key: 'The %1$s table is not okay. It is reporting the following error: %2$s. WordPress will attempt to repair this table&hellip;'
				val: '「%1$s」数据表有问题。报告的问题是：%2$s。 WordPress 正在尝试进行修复&hellip;'
			},
			rt.ArrayItem{
				key: 'Enter the email address or username of an existing user on this network to invite them to this site. That person will be sent an email asking them to confirm the invite.'
				val: '输入此站点网络中已存在用户的邮箱地址或用户名以邀请他们加入此站点。该用户将收到一封邮件，并需要他们确认该邀请。'
			},
			rt.ArrayItem{
				key: 'Enter the email address of an existing user on this network to invite them to this site. That person will be sent an email asking them to confirm the invite.'
				val: '输入此站点网络中已存在用户的邮箱地址以邀请他们加入此站点。该用户将收到一封邮件，并需要他们确认该邀请。'
			},
			rt.ArrayItem{
				key: 'Show Toolbar when viewing site'
				val: '在浏览站点时显示工具栏'
			},
			rt.ArrayItem{
				key: 'For more information, see <a href="%s">the release notes</a>.'
				val: '欲了解更多，参见<a href="%s">发行注记</a>。'
			},
			rt.ArrayItem{
				key: '<strong>Version %1$s</strong> addressed some security issues and fixed %2$s bug.'
				val: '<strong>%1$s 版本</strong>修补了安全漏洞、修正了 %2$s 个问题。'
			},
			rt.ArrayItem{
				key: '<strong>Version %1$s</strong> addressed a security issue and fixed %2$s bug.'
				val: '<strong>%1$s 版本</strong>修补了安全漏洞、修正了 %2$s 个问题。'
			},
			rt.ArrayItem{
				key: '<strong>Version %1$s</strong> addressed %2$s bug.'
				val: '<strong>%1$s 版本</strong>修复了 %2$s 个问题。'
			},
			rt.ArrayItem{
				key: '<strong>Version %s</strong> addressed some security issues.'
				val: '<strong>版本 %s</strong> 修正了一些安全问题。'
			},
			rt.ArrayItem{ key: 'Maintenance and Security Release', val: '维护和安全更新' },
			rt.ArrayItem{ key: 'Security Release', val: '安全更新' },
			rt.ArrayItem{ key: 'Maintenance Release', val: '维护更新' },
			rt.ArrayItem{ key: 'What&#8217;s New', val: '更新内容' },
			rt.ArrayItem{
				key: 'This screen allows you to choose your permalink structure. You can choose from common settings or create custom URL structures.'
				val: '此界面可以让您选择您的固定链接结构。您可以选择常见的设置或建立自定义 URL 结构。'
			},
			rt.ArrayItem{
				key: 'Welcome to WordPress %1$s. <a href="%2$s">Learn more</a>.'
				val: '欢迎使用 WordPress %1$s。<a href="%2$s">了解更多</a>。'
			},
			rt.ArrayItem{
				key: 'You can upload media files here without creating a post first. This allows you to upload files to use with posts and pages later and/or to get a web link for a particular file that you can share. There are three options for uploading files:'
				val: '您可以不创建文章，直接上传媒体文件。这样，您就可以日后将这些媒体文件用在文章或页面中；与此同时，您也得到了一个可用于分享的网络链接。您有如下三种上传文件方式可供选择：'
			},
			rt.ArrayItem{ key: 'Adding Tags', val: '标签的添加' },
			rt.ArrayItem{ key: 'Adding Categories', val: '添加分类' },
			rt.ArrayItem{ key: 'Troubleshooting', val: '故障排除' },
			rt.ArrayItem{ key: 'How to Update', val: '如何更新' },
			rt.ArrayItem{
				key: 'Once you&#8217;ve saved the download file, you can use the Import function in another WordPress installation to import the content from this site.'
				val: '保存完下载的文件后，便可以在其他 WordPress 站点中使用「导入」功能进行内容导入。'
			},
			rt.ArrayItem{ key: 'Attaching Files', val: '附加文件' },
			rt.ArrayItem{
				key: 'You can also edit or move multiple posts to the Trash at once. Select the posts you want to act on using the checkboxes, then select the action you want to take from the Bulk actions menu and click Apply.'
				val: '您也可以一次编辑或移动多篇文章到回收站。使用复选框选择您要操作的文章，然后从批量操作菜单中选择您要采取的操作，然后点击「应用」按钮。'
			},
			rt.ArrayItem{ key: 'Available Actions', val: '可进行的操作' },
			rt.ArrayItem{
				key: 'You can customize the display of this screen&#8217;s contents in a number of ways:'
				val: '您可以通过以下方法来自定义本页面内容的显示方式：'
			},
			rt.ArrayItem{ key: 'Screen Content', val: '页面内容' },
			rt.ArrayItem{
				key: 'This screen provides access to all of your posts. You can customize the display of this screen to suit your workflow.'
				val: '本页面提供文章相关的所有功能。您可以自定义页面的样式来使工作更顺手。'
			},
			rt.ArrayItem{
				key: 'If the importer you need is not listed, <a href="%s">search the plugin directory</a> to see if an importer is available.'
				val: '若上面没有您希望使用的导入工具，请尝试<a href="%s">搜索插件目录</a>以寻找适用的导入工具。'
			},
			rt.ArrayItem{ key: 'Moderating Comments', val: '评论的审核' },
			rt.ArrayItem{
				key: 'If you want to convert your categories to tags (or vice versa), use the <a href="%s">Categories and Tags Converter</a> available from the Import screen.'
				val: '如果您想将分类转为标签（或者反过来），可以选用「导入」页面上的<a href="%s">分类与标签转换器</a>来实现。'
			},
			rt.ArrayItem{ key: 'Adding Plugins', val: '插件的添加' },
			rt.ArrayItem{ key: 'Adding Themes', val: '安装主题' },
			rt.ArrayItem{
				key: 'Subscribers can read comments/comment/receive newsletters, etc. but cannot create regular site content.'
				val: '订阅者可以阅读评论、发表评论、接收新闻等，但不能发布诸如文章、页面等常规站点内容。'
			},
			rt.ArrayItem{
				key: 'Authors can publish and manage their own posts, and are able to upload files.'
				val: '作者可以发布和管理自己的文章，可以上传文件。'
			},
			rt.ArrayItem{
				key: 'Here is a basic overview of the different user roles and the permissions associated with each one:'
				val: '如下是各种用户角色和它们所拥有的权限：'
			},
			rt.ArrayItem{ key: 'User Roles', val: '用户角色' },
			rt.ArrayItem{
				key: 'Remember to click the Add User button at the bottom of this screen when you are finished.'
				val: '请不要忘记在完成表单后点击页面下方的「添加用户」按钮。'
			},
			rt.ArrayItem{
				key: 'To add a new user to your site, fill in the form on this screen and click the Add User button at the bottom.'
				val: '要向您的站点新增用户，填写本页上的表单，并点击下方的「添加用户」按钮。'
			},
			rt.ArrayItem{ key: 'Custom Structures', val: '自定义结构' },
			rt.ArrayItem{ key: 'Common Settings', val: '常用设置' },
			rt.ArrayItem{
				key: 'Permalinks are the permanent URLs to your individual pages and blog posts, as well as your category and tag archives. A permalink is the web address used to link to your content. The URL to each post should be permanent, and never change &#8212; hence the name permalink.'
				val: '固定链接是指向您的文章、页面、分类归档和标签归档等网页的固定 URL。之所以称之为「固定链接」，是因为链接到每篇文章的 URL 应该永久固定，不应修改。'
			},
			rt.ArrayItem{
				key: 'You can submit content in several different ways; this screen holds the settings for all of them. The top section controls the editor within the dashboard, while the rest control external publishing methods. For more information on any of these methods, use the documentation links.'
				val: '您可以在本页面设置撰写文章的方式。顶端的几个选项是有关在 WordPress 仪表盘的「编辑」选项；剩余的项目与通过其他发布方式有关。欲了解关于其他发布方式的信息，请参考文档链接。'
			},
			rt.ArrayItem{
				key: 'Uploading Files allows you to choose the folder and path for storing your uploaded files.'
				val: '「文件上传」的内容决定存放您上传文件的目录和路径。'
			},
			rt.ArrayItem{
				key: 'Installing themes on Multisite can only be done from the Network Admin section.'
				val: '只能在「管理网络」中为多站点安装主题。'
			},
			rt.ArrayItem{
				key: 'If desired, WordPress will automatically alert various services of your new posts.'
				val: '如有需要，WordPress 可自动在您发布新文章时通知若干网络服务。'
			},
			rt.ArrayItem{ key: 'Post Via Email', val: '通过邮件发布文章' },
			rt.ArrayItem{
				key: 'This screen provides many options for controlling the management and display of comments and links to your posts/pages. So many, in fact, they will not all fit here! :) Use the documentation links to get information on what each discussion setting does.'
				val: '此界面提供了若干用于管理和显示评论以及链接制文章 / 页面的选项。 请参阅文档链接以了解每个讨论设置的项。'
			},
			rt.ArrayItem{
				key: 'You can change your password, turn on keyboard shortcuts, change the color scheme of your WordPress administration screens, and turn off the WYSIWYG (Visual) editor, among other things. You can hide the Toolbar (formerly called the Admin Bar) from the front end of your site, however it cannot be disabled on the admin screens.'
				val: '您可以修改密码、启用键盘快捷键、更换 WordPress 管理界面配色、关闭可视化编辑器等。您也可以选择在站点前端隐藏工具栏（前称「管理工具栏」），但不能在管理界面隐藏。'
			},
			rt.ArrayItem{
				key: 'This sidebar is no longer available and does not show anywhere on your site. Remove each of the widgets below to fully remove this inactive sidebar.'
				val: '这个边栏不再可用，当前不在站点的任何位置使用。要移除这个未启用的边栏，请移除其下所有的小工具。'
			},
			rt.ArrayItem{ key: 'Inactive Sidebar (not used)', val: '未启用的边栏' },
			rt.ArrayItem{
				key: 'Clicking <strong>Select Files</strong> opens a navigation window showing you files in your operating system. Selecting <strong>Open</strong> after clicking on the file you want activates a progress bar on the uploader screen.'
				val: '点击<strong>选择文件</strong>后将弹出您操作系统的文件选择窗口。选择您需要上传的文件，单击<strong>打开</strong>按钮后，文件开始上传。进度条会自动出现，指示上传状态。'
			},
			rt.ArrayItem{
				key: '<strong>Drag and drop</strong> your files into the area below. Multiple files are allowed.'
				val: '将文件<strong>拖放</strong>到下方的区域。您可以同时拖放多个文件。'
			},
			rt.ArrayItem{
				key: 'You can assign keywords to your posts using <strong>tags</strong>. Unlike categories, tags have no hierarchy, meaning there is no relationship from one tag to another.'
				val: '您可为文章指定一些关键词，这些关键词叫做<strong>标签</strong>。与分类不同的是，标签没有层级关系，换句话说就是标签之间没有关联。'
			},
			rt.ArrayItem{
				key: 'You can create groups of links by using Link Categories. Link Category names must be unique and Link Categories are separate from the categories you use for posts.'
				val: '您可以使用「链接分类」创建一组链接。链接分类的名字必须是唯一的，且链接分类和文章分类相对独立。'
			},
			rt.ArrayItem{ key: 'Missing Widgets', val: '丢失的小工具' },
			rt.ArrayItem{ key: 'Removing and Reusing', val: '移除后重新使用' },
			rt.ArrayItem{
				key: 'If a media file has not been attached to any content, you will see that in the Uploaded To column, and can click on Attach to launch a small popup that will allow you to search for existing content and attach the file.'
				val: '若某个多媒体文件未被加入任何文章或页面，您将在这个文件的「上传至」一栏看到「现在附加到文章或页面」链接；点击它，将会弹出一个新的窗口，您可搜索现有的内容，并将其加入文章或页面。'
			},
			rt.ArrayItem{
				key: 'All the files you&#8217;ve uploaded are listed in the Media Library, with the most recent uploads listed first. You can use the Screen Options tab to customize the display of this screen.'
				val: '您上传的所有文件都在「媒体库」界面中按上传时间顺序列出，最新上传的显示在最前面。您可以在「显示选项」选项卡中自定义此页面。'
			},
			rt.ArrayItem{
				key: 'You can also perform the same types of actions, including narrowing the list by using the filters, acting on a page using the action links that appear when you hover over a row, or using the Bulk actions menu to edit the metadata for multiple pages at once.'
				val: '您可以进行同样的操作，比如使用过滤器筛选列表项、使用鼠标悬停的方式进行管理，或使用「批量操作」功能来同时编辑多个文章的属性。'
			},
			rt.ArrayItem{
				key: 'Managing pages is very similar to managing posts, and the screens can be customized in the same way.'
				val: '管理页面的方法和管理文章的方法类似，本界面也可以用相同的方式自定义。'
			},
			rt.ArrayItem{
				key: 'Pages are similar to posts in that they have a title, body text, and associated metadata, but they are different in that they are not part of the chronological blog stream, kind of like permanent posts. Pages are not categorized or tagged, but can have a hierarchy. You can nest pages under other pages by making one the &#8220;Parent&#8221; of the other, creating a group of pages.'
				val: '页面和文章类似——它们都有标题、正文以及附带的相关信息；但与文章不同的是，它们类似永久的文章，而往往不像一般的博客文章那样，随着时间流逝逐渐淡出人们的视线。页面不属于任何一个分类，亦不能拥有标签，但是页面之间可以有层级关系。您可将一个页面附属在另一个「父级页面」之下，构建一个页面群组。'
			},
			rt.ArrayItem{
				key: 'Many people take advantage of keyboard shortcuts to moderate their comments more quickly. Use the link to the side to learn more.'
				val: '许多用户使用键盘快捷键来提高审核效率。点击右侧的链接可以了解更多。'
			},
			rt.ArrayItem{
				key: 'In the <strong>Author</strong> column, in addition to the author&#8217;s name, email address, and site URL, the commenter&#8217;s IP address is shown. Clicking on this link will show you all the comments made from this IP address.'
				val: '在<strong>作者</strong>列中，除了作者姓名、邮箱地址和网站 URL 之外，还显示评论者的 IP 地址。单击此链接将显示从此 IP 地址发表的所有评论。'
			},
			rt.ArrayItem{
				key: 'You can manage comments made on your site similar to the way you manage posts and other content. This screen is customizable in the same ways as other management screens, and you can act on comments using the on-hover action links or the bulk actions.'
				val: '您可以使用与管理文章相同的方式来管理评论。与其他管理页面一样，您可以用相同方法随意自定义本界面。将鼠标光标悬停在某条评论上，可以快速管理评论；使用批量管理功能也是十分有效的方法。'
			},
			rt.ArrayItem{
				key: 'Links in the Toolbar at the top of the screen connect your dashboard and the front end of your site, and provide access to your profile and helpful WordPress information.'
				val: '上方「工具栏」上的链接将仪表盘和站点前端连接起来，默认在站点的所有页面显示，提供您的个人资料信息及有用的 WordPress 信息。'
			},
			rt.ArrayItem{ key: 'Deleting Links', val: '链接的删除' },
			rt.ArrayItem{
				key: 'Links may be separated into Link Categories; these are different than the categories used on your posts.'
				val: '可以使用「链接分类」来组织链接。链接分类和文章分类不太相同。'
			},
			rt.ArrayItem{
				key: '<a href="%1$s">Learn more about WordPress %2$s</a>.'
				val: '<a href="%1$s">了解 WordPress %2$s</a>。'
			},
			rt.ArrayItem{
				key: '<strong>Edit</strong> takes you to the editable profile screen for that user. You can also reach that screen by clicking on the username.'
				val: '点击「<strong>编辑</strong>」可在个人资料编辑器中编辑该用户。当然，直接点击用户名也是可以的。'
			},
			rt.ArrayItem{
				key: 'Hovering over a row in the users list will display action links that allow you to manage users. You can perform the following actions:'
				val: '将鼠标光标悬停在用户列表中的某一行，操作链接将会显示出来，您可以通过它们快速管理用户。您可进行下列操作：'
			},
			rt.ArrayItem{
				key: 'You can view all posts made by a user by clicking on the number under the Posts column.'
				val: 'WordPress 可列出一个用户发布的所有文章——点击列表中相应用户「文章」一栏的数字来查看该人所写的文章。'
			},
			rt.ArrayItem{
				key: 'You can hide/display columns based on your needs and decide how many users to list per screen using the Screen Options tab.'
				val: '您可在「显示选项」中按需隐藏或显示各个栏目，并决定每页显示的用户数。'
			},
			rt.ArrayItem{ key: 'Managing Pages', val: '页面的管理' },
			rt.ArrayItem{
				key: '<strong>Preview</strong> will show you what your draft post will look like if you publish it. View will take you to your live site to view the post. Which link is available depends on your post&#8217;s status.'
				val: '点击<strong>预览 / 查看</strong>，您的浏览器将跳转到前台，为您展示文章发布后的效果，或访问已经发布的这篇文章。'
			},
			rt.ArrayItem{
				key: '<strong>Trash</strong> removes your post from this list and places it in the Trash, from which you can permanently delete it.'
				val: '点击<strong>移至回收站</strong>，该文章将会从列表中移除，并自动移至回收站。在回收站中，您可以将其永久删除。'
			},
			rt.ArrayItem{
				key: '<strong>Quick Edit</strong> provides inline access to the metadata of your post, allowing you to update post details without leaving this screen.'
				val: '点击<strong>快速编辑</strong>，您无须跳转到其他页面，在本页内就能对文章属性进行更改。'
			},
			rt.ArrayItem{
				key: '<strong>Edit</strong> takes you to the editing screen for that post. You can also reach that screen by clicking on the post title.'
				val: '点击<strong>编辑</strong>可在编辑器中编辑该文章。直接点击文章标题也可以达到同样的效果。'
			},
			rt.ArrayItem{
				key: 'Because this is a multisite installation, you may add accounts that already exist on the Network by specifying a username or email, and defining a role. For more options, such as specifying a password, you have to be a Network Administrator and use the hover link under an existing user&#8217;s name to Edit the user profile under Network Admin > All Users.'
				val: '由于当前多站点功能已经开启，您可以直接通过输入用户名或邮箱地址的方式将站点网络中的现有用户添加到站点中，然后为其指定用户角色。如需修改密码等其他信息，您需要拥有网络管理员的权限，访问「管理网络」>「所有用户」，然后将鼠标放置在用户名上方，点击出现的「编辑」链接。'
			},
			rt.ArrayItem{ key: 'Welcome to WordPress 7.0', val: '欢迎使用 WordPress 7.0' },
			rt.ArrayItem{
				key: 'Go to Dashboard &rarr; Home'
				val: '转到「仪表盘」 &rarr; 「首页」页面'
			},
			rt.ArrayItem{
				key: 'Go to Dashboard &rarr; Updates'
				val: '转到「仪表盘」 &rarr; 「更新」页面'
			},
			rt.ArrayItem{ key: 'Profile updated.', val: '个人资料已更新。' },
			rt.ArrayItem{
				key: 'You are using the multi-file uploader. Problems? Try the <button %s>browser uploader</button> instead.'
				val: '您正在使用多文件上传器。遇到问题？请尝试使用<button %s>浏览器上传器</button>。'
			},
			rt.ArrayItem{
				key: "Hi,\n\nYou've been invited to join '%1$s' at\n%2$s with the role of %3$s.\n\nPlease click the following link to confirm the invite:\n%4$s"
				val: '您好，\n\n我们邀您加入「%1$s」并成为 %3$s。站点地址为：%2$s\n请点击以下链接确认加入：%4$s'
			},
			rt.ArrayItem{ key: 'Core Developer', val: '核心开发者' },
			rt.ArrayItem{ key: 'No valid plugins were found.', val: '没有找到有效的插件。' },
			rt.ArrayItem{
