				val: '无法安装这个包。'
			},
			rt.ArrayItem{ key: 'Attachment Post URL', val: '文章附件 URL' },
			rt.ArrayItem{ key: 'admin menuAll Links', val: '全部链接' },
			rt.ArrayItem{ key: '%s plugins', val: '%s 个插件' },
