			rt.ArrayItem{ key: 'The %s table is okay.', val: '%s 数据表正常。' },
			rt.ArrayItem{ key: 'View version %s details.', val: '查看版本 %s 详情。' },
			rt.ArrayItem{ key: 'Tumblr', val: 'Tumblr' },
			rt.ArrayItem{
				key: '<a href="%1$s" class="update-browser-link">Update %2$s</a> or learn how to <a href="%3$s" class="browse-happy-link">browse happy</a>'
				val: '<a href="%1$s" class="update-browser-link">升级您的 %2$s</a>，或了解一下<a href="%3$s" class="browse-happy-link">先进的浏览器</a>的有关信息'
			},
			rt.ArrayItem{
				key: 'Scale images to match the large size selected in %1$simage options%2$s (%3$d &times; %4$d).'
				val: '按照 %1$s 图片选项 %2$s 的设置，将图片剪裁到「大尺寸」（%3$d &times; %4$d）。'
			},
			rt.ArrayItem{ key: 'Audio, Video, or Other File', val: '音频、视频等文件' },
			rt.ArrayItem{
				key: 'Insert media from another website'
				val: '插入来自其他网站的媒体'
			},
			rt.ArrayItem{
				key: '<strong>Error:</strong> Could not connect to the server. Please verify the settings are correct.'
				val: '<strong>错误：</strong>无法连接到服务器。请确认设置是否正确。'
			},
			rt.ArrayItem{
				key: '<strong>Drag and Drop</strong> &mdash; To rearrange the boxes, drag and drop by clicking on the title bar of the selected box and releasing when you see a gray dotted-line rectangle appear in the location you want to place the box.'
				val: '<strong>拖放功能</strong>——要重新排列模块，按住模块的标题栏，将其拖动到您希望的位置，在灰色虚线框出现后放开鼠标按键，即可调整模块的位置。'
			},
			rt.ArrayItem{
				key: 'You can use the following controls to arrange your Dashboard screen to suit your workflow. This is true on most other administration screens as well.'
				val: '您可以根据您的工作方式，使用下列操作方式安排仪表盘的页面布局。大部分其他管理页面也支持页面布局调整功能。'
			},
			rt.ArrayItem{
				key: 'The left-hand navigation menu provides links to all of the WordPress administration screens, with submenu items displayed on hover. You can minimize this menu to a narrow icon strip by clicking on the Collapse Menu arrow at the bottom.'
				val: '左侧的导航菜单提供了所有 WordPress 管理页面的链接。将鼠标移至菜单项目上，子菜单将会显示。您可以使用最下方的「收起菜单」箭头来收起菜单，菜单项将以小图标的形式显示。'
			},
			rt.ArrayItem{ key: 'Updates %s', val: '更新 %s' },
			rt.ArrayItem{ key: 'Installed Plugins', val: '已安装插件' },
			rt.ArrayItem{ key: 'Plugins %s', val: '插件 %s' },
			rt.ArrayItem{ key: 'All Users', val: '所有用户' },
