			rt.ArrayItem{ key: 'Version %s', val: '%s 版本' },
			rt.ArrayItem{
				key: 'Update Available <span class="count">(%s)</span>'
				val: '可供更新<span class="count">（%s）</span>'
			},
			rt.ArrayItem{ key: 'Delete Site', val: '删除站点' },
			rt.ArrayItem{ key: 'Settings saved.', val: '设置已保存。' },
			rt.ArrayItem{ key: 'For more information:', val: '更多信息：' },
			rt.ArrayItem{ key: 'About Pages', val: '关于页面' },
			rt.ArrayItem{ key: 'Title and Post Editor', val: '标题和文章编辑器' },
			rt.ArrayItem{ key: 'Customizing This Display', val: '自定义显示方式' },
			rt.ArrayItem{
				key: 'Note: Neither of these options blocks access to your site &mdash; it is up to search engines to honor your request.'
				val: '注意：这些设置并不能彻底阻止搜索引擎访问您的站点——具体行为还取决于它们是否遵循您的要求。'
			},
			rt.ArrayItem{ key: 'Post name', val: '文章名' },
			rt.ArrayItem{ key: 'sample permalink structuresample-post', val: 'sample-post' },
			rt.ArrayItem{ key: 'sample permalink basearchives', val: 'archives' },
			rt.ArrayItem{
				key: 'This importer is not installed. Please install importers from <a href="%s">the main site</a>.'
				val: '尚未安装该导入工具。请从<a href="%s">主站点</a>安装导入工具。'
			},
			rt.ArrayItem{ key: 'Site Language', val: '站点语言' },
			rt.ArrayItem{
				key: 'Attempt to notify any blogs linked to from the post'
				val: '尝试通知文章中链接的博客'
			},
			rt.ArrayItem{
				key: "Hi,\nYou've been invited to join '%1$s' at\n%2$s with the role of %3$s.\nIf you do not want to join this site please ignore\nthis email. This invitation will expire in a few days.\n\nPlease click the following link to activate your user account:\n%%s"
				val: '您好，\n\n我们邀您加入「%1$s」并成为 %3$s。站点地址为：\n%2$s\n如果您不想加入，您只需忽略本邮件。\n本邀请函仅在几天内有效。\n\n如果您愿意，请点击以下链接来激活您的用户账户：\n%%s'
			},
			rt.ArrayItem{ key: 'Post Formats', val: '文章形式' },
			rt.ArrayItem{ key: 'Full Width Template', val: '全宽模板' },
			rt.ArrayItem{ key: 'Featured Images', val: '特色图片' },
			rt.ArrayItem{ key: 'Featured Image Header', val: '页眉特色图片' },
			rt.ArrayItem{
				key: "It looks like you're using an old version of %s. For the best WordPress experience, please update your browser."
				val: '看起来您正在使用旧版本的 %s。要获得最佳的 WordPress 体验，请升级您的浏览器。'
			},
			rt.ArrayItem{
				key: "It looks like you're using an insecure version of %s. Using an outdated browser makes your computer unsafe. For the best WordPress experience, please update your browser."
				val: '看起来您正在使用不安全的 %s。使用过时的浏览器会使您的计算机变得不安全。要获得最佳的 WordPress 体验，请升级您的浏览器。'
			},
			rt.ArrayItem{
				key: 'There are some invalid menu items. Please check or delete them.'
				val: '发现无效的菜单项。请进行检查，或删除它们。'
			},
			rt.ArrayItem{ key: 'term nameName', val: '名称' },
			rt.ArrayItem{ key: 'meta nameName', val: '名称' },
			rt.ArrayItem{ key: 'theme nameName', val: '名称' },
			rt.ArrayItem{
				key: 'You can find additional themes for your site by using the Theme Browser/Installer on this screen, which will display themes from the <a href="%s">WordPress Theme Directory</a>. These themes are designed and developed by third parties, are available free of charge, and are compatible with the license WordPress uses.'
				val: '通过主题浏览 / 安装器，您可以为您的站点安装其他主题。主题浏览 / 安装器显示的是来自 <a href="%s">WordPress.org 主题目录</a> 的主题。这些主题都是由第三方设计开发并免费提供的，且与 WordPress 所用的许可证相兼容。'
			},
			rt.ArrayItem{
				key: 'If you would like to see more plugins to choose from, click on the &#8220;Add Plugin&#8221; button and you will be able to browse or search for additional plugins from the <a href="%s">WordPress Plugin Directory</a>. Plugins in the WordPress Plugin Directory are designed and developed by third parties, and are compatible with the license WordPress uses. Oh, and they are free!'
				val: '如果您想查看更多可供选择的插件，请点击「安装插件」按钮，您就可以从<a href="%s">WordPress.org 插件目录</a>中浏览或搜索更多插件。 WordPress 插件目录中的插件是由第三方设计开发的，且与 WordPress 所用的版权许可证相兼容。最棒的是，它们都是免费的！'
			},
			rt.ArrayItem{
				key: 'The uploaded file exceeds the %s directive that was specified in the HTML form.'
				val: '上传的文件大小超过 HTML 表单所定义的 %s 值。'
			},
			rt.ArrayItem{ key: 'External Libraries', val: '外部库' },
			rt.ArrayItem{ key: 'Network Setup', val: '配置网络' },
			rt.ArrayItem{ key: 'Available Tools', val: '可用工具' },
			rt.ArrayItem{
				key: 'Translate this to be the equivalent of English Translators in your language for the credits page Translators sectionTranslators'
				val: '简体中文翻译贡献者'
			},
			rt.ArrayItem{
				key: 'Every plugin and theme in WordPress.org&#8217;s directory is 100%% GPL or a similarly free and compatible license, so you can feel safe finding <a href="%1$s">plugins</a> and <a href="%2$s">themes</a> there. If you get a plugin or theme from another source, make sure to <a href="%3$s">ask them if it&#8217;s GPL</a> first. If they do not respect the WordPress license, it is not recommended to use them.'
				val: '在 WordPress.org 插件和主题目录中的内容均 100%% 遵循 GPL 或相似相兼容的自由许可证发布，因此您可随意使用目录中的<a href="%1$s">插件</a>和<a href="%2$s">主题</a>。若您从别处得到了插件或主题，请先<a href="%3$s">询问它们是否遵循 GPL</a>。若它们不遵循 WordPress 使用的许可证，我们不建议您使用。'
			},
			rt.ArrayItem{
				key: 'WordPress grows when people like you tell their friends about it, and the thousands of businesses and services that are built on and around WordPress share that fact with their users. The WordPress community is flattered every time someone spreads the good word, just make sure to <a href="%s">check out the WordPress Foundation trademark guidelines</a> first.'
				val: 'WordPress 凭借您的力量进行宣传，并发展壮大——每次您和朋友赞扬它，或者一些公司使用 WordPress 来制作公司网站，甚至创建一些服务时 WordPress 社区都会感到很荣幸，不过希望您<a href="%s">关注 WordPress 社区的商标使用准则</a>。'
			},
			rt.ArrayItem{ key: 'All Comments', val: '所有评论' },
			rt.ArrayItem{ key: 'Lead Developer', val: '首席开发者' },
			rt.ArrayItem{ key: 'Cofounder, Project Lead', val: '创始人、项目领导者' },
			rt.ArrayItem{
				key: 'Core Contributors to WordPress %s'
				val: 'WordPress %s 版本的核心贡献者'
