			},
			rt.ArrayItem{
				key: 'If you do not want to upload your own image, you can use one of these cool headers, or show a random one.'
				val: '若您现在不想上传您自己的图片，可从这些精美的页眉图片中选择，或让 WordPress 在每次显示页面时随机挑选。'
