				val: '此插件可能已经在站点网络中的其他站点上启用。'
			},
			rt.ArrayItem{ key: 'Default Post Format', val: '默认文章形式' },
			rt.ArrayItem{
				key: 'Any edits to files from this screen will be reflected on all sites in the network.'
				val: '从此页面对文件的任何编辑都将应用到站点网络中的所有站点。'
			},
			rt.ArrayItem{
				key: 'This screen lists all the existing users for your site. Each user has one of five defined roles as set by the site admin: Site Administrator, Editor, Author, Contributor, or Subscriber. Users with roles other than Administrator will see fewer options in the dashboard navigation when they are logged in, based on their role.'
				val: '本页面列出了您站点当前的所有用户。根据站点管理员的意愿，每位用户都有下列五种用户角色中的其中一种：站点管理员、编辑、作者、贡献者或订阅者。在用户登录到仪表盘后，权限低于管理员角色的用户，只能基于其权限看到部分选项。'
			},
			rt.ArrayItem{
				key: 'If you want to make changes but do not want them to be overwritten when the plugin is updated, you may be ready to think about writing your own plugin. For information on how to edit plugins, write your own from scratch, or just better understand their anatomy, check out the links below.'
				val: '如果您想进行更改但不希望在更新插件时丢失更改，您可以考虑编写自己的插件。 如需了解如何编辑插件、从头开始编写自己的插件或只是想了解插件的结构，请查看以下链接。'
			},
			rt.ArrayItem{
				key: 'The boxes on your Dashboard screen are:'
				val: '仪表盘中的模块有：'
			},
			rt.ArrayItem{ key: 'sample-page', val: 'sample-page' },
			rt.ArrayItem{ key: 'Sample Page', val: '示例页面' },
			rt.ArrayItem{ key: 'Retro (Generated)', val: '复古（自动生成）' },
			rt.ArrayItem{
				key: 'You only have one theme enabled for this site right now. Visit the Network Admin to <a href="%s">enable</a> more themes.'
				val: '您目前只安装了一个主题。您可访问「管理网络」页面来「<a href="%s">启用</a>」更多主题。'
			},
			rt.ArrayItem{
				key: 'You only have one theme enabled for this site right now. Visit the Network Admin to <a href="%1$s">enable</a> or <a href="%2$s">install</a> more themes.'
				val: '您目前只安装了一个主题。您可访问「管理网络」页面来「<a href="%1$s">启用</a>」或「<a href="%2$s">安装</a>」更多主题。'
			},
			rt.ArrayItem{
				key: 'You only have one theme installed right now. Live a little! You can choose from over 1,000 free themes in the WordPress Theme Directory at any time: just click on the <a href="%s">Install Themes</a> tab above.'
				val: '您目前只安装了一个主题，太少了吧！您可随时从 WordPress.org 主题目录中的上千种免费主题中选择：只需点击上方的<a href="%s">安装主题</a>标签。'
			},
			rt.ArrayItem{
				key: 'One or more database tables are unavailable. To allow WordPress to attempt to repair these tables, press the &#8220;Repair Database&#8221; button. Repairing can take a while, so please be patient.'
				val: '有些数据表无效。若您希望让 WordPress 尝试修复它们，请点击「修复数据库」按钮。修复过程需要一点时间，请耐心等待。'
			},
			rt.ArrayItem{
