				key: 'This is a file in your current parent theme.'
				val: '这是您当前父主题中的一个文件。'
			},
			rt.ArrayItem{
				key: 'This child theme inherits templates from a parent theme, %s.'
				val: '此主题使用从父主题「%s」继承下来的模板。'
			},
			rt.ArrayItem{ key: 'Network Enable', val: '在站点网络中启用' },
			rt.ArrayItem{
				key: 'Your WordPress database has been successfully updated!'
				val: '您的 WordPress 数据库已成功升级！'
			},
			rt.ArrayItem{ key: 'Update Complete', val: '升级完成' },
			rt.ArrayItem{ key: 'Update WordPress Database', val: '升级 WordPress 数据库' },
			rt.ArrayItem{
				key: 'The database update process may take a little while, so please be patient.'
				val: '数据库升级过程需要一点时间，请耐心等候。'
			},
			rt.ArrayItem{ key: 'Database Update Required', val: '需要升级数据库' },
			rt.ArrayItem{ key: 'No Update Required', val: '无需升级' },
			rt.ArrayItem{ key: 'WordPress &rsaquo; Update', val: 'WordPress &rsaquo; 升级' },
			rt.ArrayItem{
				key: 'You are about to install WordPress %s <strong>in English (US)</strong>. There is a chance this update will break your translation. You may prefer to wait for the localized version to be released.'
				val: '您将安装<strong>美式英语版本</strong>的 WordPress %s。这可能会破坏您当前使用的翻译。您可等待本地化版本发布后再更新。'
			},
			rt.ArrayItem{
				key: 'There is a new version of %1$s available. <a href="%2$s" %3$s>View version %4$s details</a>. <em>Automatic update is unavailable for this plugin.</em>'
				val: '%1$s 有新版本可用。<a href="%2$s" %3$s> 查看版本 %4$s 详情</a>。<em>自动更新对此插件不可用。</em>'
			},
			rt.ArrayItem{ key: 'Update Theme', val: '升级主题' },
			rt.ArrayItem{ key: 'Update Plugin', val: '升级插件' },
			rt.ArrayItem{ key: 'Theme updated successfully.', val: '主题升级成功。' },
			rt.ArrayItem{ key: 'Theme update failed.', val: '主题升级失败。' },
			rt.ArrayItem{ key: 'Plugin updated successfully.', val: '插件升级成功。' },
			rt.ArrayItem{ key: 'Plugin update failed.', val: '插件升级失败。' },
			rt.ArrayItem{ key: 'Update package not available.', val: '升级包不可用。' },
			rt.ArrayItem{ key: 'Date range:', val: '日期范围：' },
			rt.ArrayItem{ key: 'Authors:', val: '作者：' },
			rt.ArrayItem{
				key: 'This will contain all of your posts, pages, comments, custom fields, terms, navigation menus, and custom posts.'
				val: '选择此项，则将包含您站点的所有文章、页面、评论、自定义字段、条目信息（分类和标签等）、导航菜单以及自定义文章。'
			},
			rt.ArrayItem{ key: 'All content', val: '所有内容' },
			rt.ArrayItem{ key: 'Choose what to export', val: '选择导出的内容' },
			rt.ArrayItem{
				key: 'commentsMine <span class="count">(%s)</span>'
				val: '我的<span class="count">（%s）</span>'
			},
			rt.ArrayItem{ key: '%s &#8212; WordPress', val: '%s &#8212; WordPress' },
			rt.ArrayItem{ key: 'column nameIn Response To', val: '回应给' },
			rt.ArrayItem{
				key: 'The Available Widgets section contains all the widgets you can choose from. Once you drag a widget into a sidebar, it will open to allow you to configure its settings. When you are happy with the widget settings, click the Save button and the widget will go live on your site. If you click Delete, it will remove the widget.'
				val: '您可从「可用小工具」区域选择需要的小工具。在拖拽其至边栏后，它将自动展开，以便您配置其设置选项。当您设置完毕后，请点击「保存」按钮，改动才会生效。点击「删除」将移除该小工具。'
			},
			rt.ArrayItem{
				key: 'Remember to click Update to save metadata entered or changed.'
				val: '在完成后请不要忘记点击「更新媒体」。'
			},
			rt.ArrayItem{
				key: 'Note that you crop the image by clicking on it (the Crop icon is already selected) and dragging the cropping frame to select the desired part. Then click Save to retain the cropping.'
				val: '裁切图片：请点击图片，并将裁切选区调整至您希望裁下的区域。然后点击「保存」以保存图片。'
			},
			rt.ArrayItem{
				key: 'For images only, you can click on Edit Image under the thumbnail to expand out an inline image editor with icons for cropping, rotating, or flipping the image as well as for undoing and redoing. The boxes on the right give you more options for scaling the image, for cropping it, and for cropping the thumbnail in a different way than you crop the original image. You can click on Help in those boxes to get more information.'
				val: '对于图片，您可点击缩略图下方的「编辑图片」，之后就会弹出一个快捷图片编辑器——您可以裁切、旋转、翻转图片。您还可以撤销或重做操作。在编辑器的右侧，您可以对图片剪裁等进行更详尽的设置。您可以点击「帮助」以了解更多。'
			},
			rt.ArrayItem{
				key: 'This screen allows you to edit fields for metadata in a file within the media library.'
				val: '在此页面，您可编辑媒体库中文件的属性。'
			},
			rt.ArrayItem{ key: 'Email or Username', val: '邮箱或用户名' },
			rt.ArrayItem{ key: 'Search installed themes', val: '搜索已安装主题' },
			rt.ArrayItem{
				key: '<strong>Please Note:</strong> Any customizations you have made to theme files will be lost. Please consider using <a href="%s">child themes</a> for modifications.'
				val: '<strong>请注意：</strong>所有之前对主题文件的修改都将丢失。请考虑使用<a href="%s">子主题</a>方式来对主题做出修改。'
			},
			rt.ArrayItem{
				key: 'postsSticky <span class="count">(%s)</span>'
				val: '置顶<span class="count">（%s）</span>'
			},
			rt.ArrayItem{ key: 'Check again.', val: '再次检查。' },
