			rt.ArrayItem{ key: 'Apply Filters', val: '应用筛选条件' },
			rt.ArrayItem{ key: 'Editor Style', val: '编辑器样式支持' },
			rt.ArrayItem{
				key: 'To perform the requested action, WordPress needs to access your web server.'
				val: '要执行请求的操作，WordPress 需要访问您网页服务器的权限。'
