			rt.ArrayItem{ key: 'Current Page', val: '当前页' },
			rt.ArrayItem{
				key: 'No themes match your request.'
				val: '没有符合要求的主题。'
			},
			rt.ArrayItem{ key: 'Search Sites', val: '搜索站点' },
			rt.ArrayItem{ key: 'Create a New User', val: '创建新用户' },
			rt.ArrayItem{ key: 'You have %1$s and %2$s.', val: '您有 %1$s 和 %2$s。' },
			rt.ArrayItem{ key: '%s site', val: '%s 个站点' },
			rt.ArrayItem{ key: '%s user', val: '%s 位用户' },
			rt.ArrayItem{
				key: 'https://wordpress.org/news/feed/'
				val: 'https://wordpress.org/news/feed/'
			},
			rt.ArrayItem{ key: 'https://wordpress.org/news/', val: 'https://cn.wordpress.org/news/' },
			rt.ArrayItem{
				key: '(Signup has been disabled. Only members of this site can comment.)'
				val: '（已禁止注册新用户。只有该站点的成员可以进行评论。）'
			},
			rt.ArrayItem{
				key: 'There is a new version of %1$s available. <a href="%2$s" %3$s>View version %4$s details</a>.'
				val: '%1$s 有新版本可用。<a href="%2$s" %3$s> 查看版本 %4$s 详情</a>。'
			},
			rt.ArrayItem{ key: 'Go to Themes page', val: '转到「主题」页面' },
			rt.ArrayItem{
				key: 'Go to WordPress Updates page'
				val: '转到「WordPress 更新」页面'
			},
			rt.ArrayItem{ key: 'Go to Plugins page', val: '转到「插件」页面' },
			rt.ArrayItem{
				key: 'Click Save Menu to make pending menu items public.'
				val: '点击「保存菜单」使刚刚做出的改动于前台生效。'
			},
			rt.ArrayItem{ key: 'Storage Space', val: '储存空间' },
			rt.ArrayItem{ key: 'Create a New Site', val: '创建新站点' },
			rt.ArrayItem{
				key: 'Images of exactly <strong>%1$d &times; %2$d pixels</strong> will be used as-is.'
				val: '使用图片的<strong>%1$d &times; %2$d 像素</strong>。'
			},
			rt.ArrayItem{ key: 'Crop and Publish', val: '剪裁并发布' },
			rt.ArrayItem{
				key: 'XFN stands for <a href="https://gmpg.org/xfn/">XHTML Friends Network</a>, which is optional. WordPress allows the generation of XFN attributes to show how you are related to the authors/owners of the site to which you are linking.'
				val: 'XFN 是可选项，其含义为 <a href="https://gmpg.org/xfn/">XHTML 社交网络</a>。 WordPress 允许通过创建 XFN 属性来标识您与您的站点所链接站点作者 / 拥有者的关系。'
			},
			rt.ArrayItem{ key: 'FTP Password', val: 'FTP 密码' },
			rt.ArrayItem{ key: 'FTP Username', val: 'FTP 用户名' },
			rt.ArrayItem{ key: 'FTP/SSH Password', val: 'FTP 或 SSH 密码' },
			rt.ArrayItem{ key: 'FTP/SSH Username', val: 'FTP 或 SSH 用户名' },
			rt.ArrayItem{
				key: 'Many themes show some sidebar widgets by default until you edit your sidebars, but they are not automatically displayed in your sidebar management tool. After you make your first widget change, you can re-add the default widgets by adding them from the Available Widgets area.'
				val: '很多主题在用户自行设置边栏之前显示一些默认小工具，但是这些小工具不会在边栏管理工具中显示。当您对边栏做出改动后，原来的默认小工具将消失，您可以在「可用小工具」中找到它们并重新添加。'
			},
			rt.ArrayItem{
				key: 'You can choose what&#8217;s displayed on the homepage of your site. It can be posts in reverse chronological order (classic blog), or a fixed/static page. To set a static homepage, you first need to create two <a href="%s">Pages</a>. One will become the homepage, and the other will be where your posts are displayed.'
				val: '您可以选择在您站点的主页上显示什么。可以是按时间降序排列的文章（传统博客），也可以是固定 / 静态页面。要设置静态主页，您需要创建两个<a href="%s">页面</a>，其中一个会变成主页，而另一个将会显示您的文章。'
			},
			rt.ArrayItem{
				key: 'The Optional fields let you customize the &#8220;category&#8221; and &#8220;tag&#8221; base names that will appear in archive URLs. For example, the page listing all posts in the &#8220;Uncategorized&#8221; category could be <code>/topics/uncategorized</code> instead of <code>/category/uncategorized</code>.'
				val: '「可选」字段允许您在文章归档的 URL 中加入分类名和标签名。比如，「未分类」的文章归档页面的地址可以是<code>/topics/uncategorized</code>（默认情况下是<code>/category/uncategorized</code>）。'
			},
			rt.ArrayItem{
				key: 'When you assign multiple categories or tags to a post, only one can show up in the permalink: the lowest numbered category. This applies if your custom structure includes %1$s or %2$s.'
				val: '若您某篇文章包含多个分类或标签，且固定链接结构包含 %1$s 或 %2$s，则只有排序最靠前的分类或标签才会显示在固定链接中。'
			},
			rt.ArrayItem{
				key: 'If you pick an option other than Plain, your general URL path with structure tags (terms surrounded by %s) will also appear in the custom structure field and your path can be further modified there.'
				val: '如果您选择了「朴素」以外的选项，您的带有结构标签（被 %s 包含的词）的通用 URL 路径也将出现在自定义结构字段，您将可以在那里进一步修改您的路径。'
			},
			rt.ArrayItem{
				key: 'If you want to remove the widget but save its setting for possible future use, just drag it into the Inactive Widgets area. You can add them back anytime from there. This is especially helpful when you switch to a theme with fewer or different widget areas.'
				val: '如果您想移除某个小工具但保留其设置以备以后之用，只需将其拖拽到「未启用的小工具」区域中，在需要时，可随时拖回需要的边栏。这一点在您准备改用边栏数目更少的主题时很有用。'
			},
			rt.ArrayItem{
				key: 'To add a new user for your site, click the Add User button at the top of the screen or Add User in the Users menu section.'
				val: '要添加一位新用户到站点中，点击屏幕上方的「添加用户」按钮或用户菜单中的「添加用户」部分。'
			},
			rt.ArrayItem{
				key: 'You can set maximum sizes for images inserted into your written content; you can also insert an image as Full Size.'
				val: '您可以为插入文中的图片设置最大尺寸。亦可以「全尺寸」插入图片。'
			},
			rt.ArrayItem{
				key: 'Most themes show the site title at the top of every page, in the title bar of the browser, and as the identifying name for syndicated feeds. Many themes also show the tagline.'
				val: '大多数的主题在每个页面的顶端、浏览器标题栏、 Feed 中显示站点标题。许多主题也显示副标题。'
			},
			rt.ArrayItem{
				key: '<strong>Order</strong> &mdash; Pages are usually ordered alphabetically, but you can choose your own order by entering a number (1 for first, etc.) in this field.'
				val: '<strong>排序</strong>——页面默认按照字母表顺序进行排序。您也可以通过>为页面指定数字（1 代表在最前，2 代表其次……）来自定义页面的顺序。'
			},
			rt.ArrayItem{
				key: 'If you do not remember your credentials, you should contact your web host.'
				val: '如果您忘记了您的登录凭据（如用户名、密码），请联系您的主机提供商。'
			},
			rt.ArrayItem{
				key: 'Please enter your FTP credentials to proceed.'
				val: '请输入您的 FTP 登录凭据以继续。'
			},
			rt.ArrayItem{
				key: 'Please enter your FTP or SSH credentials to proceed.'
				val: '请输入您的 FTP 或 SSH 登录凭据以继续。'
			},
			rt.ArrayItem{
				key: 'Your profile contains information about you (your &#8220;account&#8221;) as well as some personal options related to using WordPress.'
				val: '您的个人资料包含您的个人信息和账户信息，以及使用 WordPress 的偏好设置。'
			},
			rt.ArrayItem{
				key: 'You can Upload a theme manually if you have already downloaded its ZIP archive onto your computer (make sure it is from a trusted and original source). You can also do it the old-fashioned way and copy a downloaded theme&#8217;s folder via FTP into your %s directory.'
				val: '您可以手动上传从别处下载的 .zip 主题压缩包文件（请确认其来源可靠）；也可以使用传统方式，将下载的主题文件通过 FTP 拷贝至您网站的 %s 目录中。'
			},
			rt.ArrayItem{
				key: '<strong>Send Trackbacks</strong> &mdash; Trackbacks are a way to notify legacy blog systems that you&#8217;ve linked to them. Enter the URL(s) you want to send trackbacks. If you link to other WordPress sites they&#8217;ll be notified automatically using pingbacks, and this field is unnecessary.'
				val: '<strong>发送 Trackback</strong>——Trackback 是通知旧博客系统您已链接至它们的一种方式。请输入您所希望发送 Trackback 的 URL。如果您链接到的是其他 WordPress 站点，则无须填写此栏，这些站点将自动通过 Pingback 方式通知。'
			},
			rt.ArrayItem{
				key: 'Contributors can write and manage their posts but not publish posts or upload media files.'
				val: '贡献者可以编写、管理他们的文章，但是无法发布文章、无法上传多媒体文件。'
			},
			rt.ArrayItem{
				key: 'Administrators have access to all the administration features.'
				val: '管理员可以访问所有管理功能。'
			},
			rt.ArrayItem{
				key: 'You can use the plugin file editor to make changes to any of your plugins&#8217; individual PHP files. Be aware that if you make changes, plugins updates will overwrite your customizations.'
				val: '您可以使用插件文件编辑器对插件的单个 PHP 文件进行修改。 请注意，如果您进行了修改，插件更新后将会覆盖您的自定义修改。'
			},
			rt.ArrayItem{
				key: 'If you delete a link, it will be removed permanently, as Links do not have a Trash function yet.'
				val: '若您删除一个链接，它将被永久移除。目前，链接不具备回收站功能。'
			},
			rt.ArrayItem{
				key: 'You can add links here to be displayed on your site, usually using <a href="%s">Widgets</a>. By default, links to several sites in the WordPress community are included as examples.'
				val: '您可以在这里添加在您站点中显示的链接（通常在<a href="%s">小工具</a>中显示）。我们预置了几个链接至 WordPress 社区的链接作为例子。'
			},
			rt.ArrayItem{
				key: '<strong>Slug</strong> &mdash; The &#8220;slug&#8221; is the URL-friendly version of the name. It is usually all lowercase and contains only letters, numbers, and hyphens.'
				val: '<strong>别名</strong>——「别名」是在 URL 中使用的代号，它可以令 URL 更美观。别名通常使用小写字母，只能包含字母、数字和连字符。'
			},
			rt.ArrayItem{
				key: 'You can also create posts with the <a href="%s">Press This bookmarklet</a>.'
				val: '您亦可通过<a href="%s">快速发布书签</a>来创建文章。'
			},
			rt.ArrayItem{
				key: 'Do not forget to click on the Save Changes button when you are finished.'
				val: '请不要忘记在完成时点击「保存更改」按钮。'
			},
			rt.ArrayItem{
				key: 'You can customize the look of your site without touching any of your theme&#8217;s code by using a custom background. Your background can be an image or a color.'
				val: '通过自定义背景，您无须修改模板的任何代码，就可使您的站点外观焕然一新！背景可以是图片或某种色彩。'
			},
			rt.ArrayItem{
				key: 'Editors can publish posts, manage posts as well as manage other people&#8217;s posts, etc.'
				val: '编辑可以发布文章、管理文章，亦可编辑他人发布的文章等。'
			},
			rt.ArrayItem{
				key: 'Remember to click the Update Profile button when you are finished.'
				val: '在完成后不要忘记点击「更新个人资料」。'
			},
			rt.ArrayItem{
				key: 'Required fields are indicated; the rest are optional. Profile information will only be displayed if your theme is set up to do so.'
				val: '必填项目有特殊标记，其余是选填项目。个人资料信息仅在主题需要时才可能被显示在站点前台。'
			},
			rt.ArrayItem{
				key: 'Your username cannot be changed, but you can use other fields to enter your real name or a nickname, and change which name to display on your posts.'
				val: '您的用户名不能更改，但是您可以在其他字段中输入真实姓名或昵称，即可决定在文章中显示哪个名字。'
			},
			rt.ArrayItem{
				key: 'You can also moderate the comment from this screen using the Status box, where you can also change the timestamp of the comment.'
				val: '您可以使用页面上的状态栏来审核评论，并可以修改该评论的发布时间。'
			},
			rt.ArrayItem{
				key: 'You can edit the information left in a comment if needed. This is often useful when you notice that a commenter has made a typographical error.'
				val: '若有需要，您可以编辑一条评论中的任何内容，特别是当评论者打错字的时候，这一功能十分有用。'
			},
			rt.ArrayItem{
				key: 'You can also control the display of your content in RSS feeds, including the maximum number of posts to display and whether to show full text or an excerpt. <a href="%s">Learn more about feeds</a>.'
				val: '您还可以控制您的内容在 RSS Feeds 中的显示方式，包括要显示的最大文章数量、是否显示全文或摘要。<a href="%s">了解有关 feeds 的更多信息</a>。'
			},
			rt.ArrayItem{
				key: 'This screen contains the settings that affect the display of your content.'
				val: '本页面提供有关站点内容显示方式的选项。'
			},
			rt.ArrayItem{
				key: 'UTC means Coordinated Universal Time.'
				val: 'UTC 是协调世界时。'
			},
			rt.ArrayItem{
				key: 'The fields on this screen determine some of the basics of your site setup.'
				val: '本页面中的选项决定您站点的基本配置。'
			},
			rt.ArrayItem{
				key: 'You must click the Save Changes button at the bottom of the screen for new settings to take effect.'
				val: '调整完成后，记得点击页面下方「保存更改」按钮使设置生效。'
			},
			rt.ArrayItem{
				key: 'The boxes for link name, web address, and description have fixed positions, while the others may be repositioned using drag and drop. You can also hide boxes you do not use in the Screen Options tab, or minimize boxes by clicking on the title bar of the box.'
				val: '链接名称、网址和描述模块有固定的位置，而其他模块可以使用拖拽进行排序。您还可以在「显示选项」选项卡中隐藏不使用的模块，或通过单击模块标题栏将其最小化。'
			},
			rt.ArrayItem{
				key: 'Your themes are all up to date.'
				val: '您的所有主题均为最新版本。'
			},
			rt.ArrayItem{
				key: 'Your plugins are all up to date.'
				val: '您的所有插件均为最新版本。'
			},
			rt.ArrayItem{
				key: 'While your site is being updated, it will be in maintenance mode. As soon as your updates are complete, this mode will be deactivated.'
				val: '当您升级您的站点时，站点将自动进入维护模式。升级完成后会自动退出。'
			},
			rt.ArrayItem{
				key: 'An updated version of WordPress is available.'
				val: '有新的 WordPress 版本可供升级。'
			},
			rt.ArrayItem{
				key: 'You have the latest version of WordPress.'
				val: '您使用的 WordPress 是最新版本。'
			},
			rt.ArrayItem{ key: 'Function Name&hellip;', val: '函数名&hellip;' },
			rt.ArrayItem{
				key: 'Activate Plugin &amp; Run Importer'
				val: '启用插件并运行导入工具'
			},
			rt.ArrayItem{
				key: 'You can add or edit links on this screen by entering information in each of the boxes. Only the link&#8217;s web address and name (the text you want to display on your site as the link) are required fields.'
				val: '您可以在相关模块中添加或编辑链接。只有链接的地址和名称是必填项。'
			},
			rt.ArrayItem{
				key: 'Categories can be selectively converted to tags using the <a href="%s">category to tag converter</a>.'
				val: '分类可以选择性的转换成标签，请使用<a href="%s">分类与标签转换器</a>。'
			},
			rt.ArrayItem{
				key: 'This screen lists links to plugins to import data from blogging/content management platforms. Choose the platform you want to import from, and click Install Now when you are prompted in the popup window. If your platform is not listed, click the link to search the plugin directory for other importer plugins to see if there is one for your platform.'
				val: '本页面列出了一些用于从其他博客平台或 CMS（内容管理系统）导入数据的插件。选择您原来使用的平台，当新窗口弹出时，请点击「立即安装」。若您在列表中没有找到您原来使用的平台，点击链接以在整个插件目录搜索适合您原平台的导入工具。'
			},
			rt.ArrayItem{
				key: 'Once generated, your WXR file can be imported by another WordPress site or by another blogging platform able to access this format.'
				val: '生成的 WXR 文件可在其他 WordPress 站点或其他支持该格式的博客软件中使用。'
			},
			rt.ArrayItem{
				key: 'Choose a plugin to edit from the dropdown menu and click the Select button. Click once on any file name to load it in the editor, and make your changes. Do not forget to save your changes (Update File) when you are finished.'
				val: '从下拉菜单中选择要编辑的插件，然后单击选择按钮。 单击需要编辑的文件名以将其加载到编辑器中进行编辑，完成后记得保存更改（更新的文件）。'
			},
			rt.ArrayItem{
				key: 'You can customize the display of this screen using the Screen Options tab and/or the dropdown filters above the links table.'
				val: '您可以通过「显示选项」或链接列表上方的下拉菜单过滤器来自定义本页面的显示。'
			},
			rt.ArrayItem{
				key: 'Most of the time, plugins play nicely with the core of WordPress and with other plugins. Sometimes, though, a plugin&#8217;s code will get in the way of another plugin, causing compatibility issues. If your site starts doing strange things, this may be the problem. Try deactivating all your plugins and re-activating them in various combinations until you isolate which one(s) caused the issue.'
				val: '大部分情况下，每个插件都能和其他插件及 WordPress 核心程序正常配合。但是，有时某些插件会和其他插件产生冲突，进而产生兼容性问题，如果您的站点工作异常，则可能是这个原因导致的。您可尝试禁用所有插件，再逐个启用，以排除问题。'
			},
			rt.ArrayItem{
				key: 'Enabling Accessibility Mode, via Screen Options, allows you to use Add and Edit buttons instead of using drag and drop.'
				val: '在「显示选项」中启用「无障碍模式」，您就可以使用「添加」和「编辑」按钮，而无须进行拖拽。'
			},
			rt.ArrayItem{
				key: 'Widgets may be used multiple times. You can give each widget a title, to display on your site, but it&#8217;s not required.'
				val: '大部分小工具可以多次使用。您可以为每个小工具起一个标题，通常这个标题会在站点中显示出来，但这不是必须的。'
			},
			rt.ArrayItem{
				key: 'Widgets are independent sections of content that can be placed into any widgetized area provided by your theme (commonly called sidebars). To populate your sidebars/widget areas with individual widgets, drag and drop the title bars into the desired area. By default, only the first widget area is expanded. To populate additional widget areas, click on their title bars to expand them.'
				val: '小工具是可以放置在任何边栏中的「块」。要使用小工具布置边栏，请用鼠标按住小工具的标题栏，将其拖至相应边栏的相应位置上。默认情况下，只有第一个边栏是展开的，要展开其他边栏区域，请点击它们的标题栏。'
			},
			rt.ArrayItem{
				key: '<strong>Advice:</strong> Think very carefully about your site crashing if you are live-editing the theme currently in use.'
				val: '<strong>建议：</strong>如果您在线编辑正在使用的主题，请当心您的站点崩溃。'
			},
			rt.ArrayItem{
				key: 'After typing in your edits, click Update File.'
				val: '当编辑完成时，请点击「更新文件」。'
			},
			rt.ArrayItem{
				key: 'Begin by choosing a theme to edit from the dropdown menu and clicking the Select button. A list then appears of the theme&#8217;s template files. Clicking once on any file name causes the file to appear in the large Editor box.'
				val: '自下拉菜单选取您想要编辑的主题，并点击「选择」后，即可开始编辑。列表中会出现全部的模板文件。点击其中任何一个文件，即可将其载入编辑框内。'
			},
			rt.ArrayItem{
				key: 'You can use the theme file editor to edit the individual CSS and PHP files which make up your theme.'
				val: '您可以使用主题文件编辑器来编辑构成主题的各个 CSS 和 PHP 文件。'
			},
			rt.ArrayItem{ key: '(no parent)', val: '（无父级）' },
			rt.ArrayItem{
				key: '<strong>Template</strong> &mdash; Some themes have custom templates you can use for certain pages that might have additional features or custom layouts. If so, you&#8217;ll see them in this dropdown menu.'
				val: '<strong>模板</strong>——某些主题有定制的模板，您可以用在一些您想新增功能或者自定义布局的页面上。您可以在下拉菜单中看到这些模板。'
			},
			rt.ArrayItem{
				key: '<strong>Parent</strong> &mdash; You can arrange your pages in hierarchies. For example, you could have an &#8220;About&#8221; page that has &#8220;Life Story&#8221; and &#8220;My Dog&#8221; pages under it. There are no limits to how many levels you can nest pages.'
				val: '<strong>父级</strong>——您可以以层级的方式组织您的页面。例如，您可以创建一个「关于」页面，它的下级有「人生」和「我的宠物」。层级深度不限。'
			},
			rt.ArrayItem{
				key: 'All updates have been completed.'
				val: '更新任务全部完成。'
			},
			rt.ArrayItem{
				key: 'You can change the display of this screen using the Screen Options tab to set how many items are displayed per screen and to display/hide columns in the table.'
				val: '在「显示选项」中，您可以调整每页显示的标签数量、隐藏或显示表格中的一些栏目。'
			},
			rt.ArrayItem{
				key: '<strong>Description</strong> &mdash; The description is not prominent by default; however, some themes may display it.'
				val: '<strong>描述</strong>——「描述」中的内容默认不会显示，但部分主题中可能会显示。'
			},
			rt.ArrayItem{
				key: '<strong>Name</strong> &mdash; The name is how it appears on your site.'
				val: '<strong>名称</strong>——此项目在站点上的显示名称。'
			},
			rt.ArrayItem{
				key: 'When adding a new tag on this screen, you&#8217;ll fill in the following fields:'
				val: '在此页面新增标签时，您将填写以下字段：'
			},
			rt.ArrayItem{
				key: 'When adding a new category on this screen, you&#8217;ll fill in the following fields:'
				val: '在此页面新增分类时，您将填写以下字段：'
			},
			rt.ArrayItem{
				key: 'What&#8217;s the difference between categories and tags? Normally, tags are ad-hoc keywords that identify important information in your post (names, subjects, etc) that may or may not recur in other posts, while categories are pre-determined sections. If you think of your site like a book, the categories are like the Table of Contents and the tags are like the terms in the index.'
				val: '分类和标签的区别是什么呢？通常来说，标签是临时安排的一些关键词，用来标记文章中的关键信息（名字、题目等），而其他文章或许也会拥有这个标签；分类则是预先确定的内容分区。若将您的站点比做一本书，那么分类就是书的目录，标签则是目录中索引的术语。'
			},
			rt.ArrayItem{
				key: 'You can use categories to define sections of your site and group related posts. The default category is &#8220;Uncategorized&#8221; until you change it in your <a href="%s">writing settings</a>.'
				val: '您可以使用分类来定义您站点的分区结构，并可以按不同的主题组织相关的文章。文章的默认分类为「未分类」，您可在<a href="%s">撰写设置</a>中修改它。'
			},
			rt.ArrayItem{
				key: 'You need JavaScript to choose a part of the image.'
				val: '您需要 JavaScript 支持以选择图片的一部分。'
			},
			rt.ArrayItem{ key: 'Crop Header Image', val: '剪裁页眉图片' },
			rt.ArrayItem{ key: 'Image Upload Error', val: '图片上传发生错误' },
			rt.ArrayItem{ key: 'Text Color', val: '文本颜色' },
			rt.ArrayItem{ key: 'Restore Original Header Image', val: '重设页眉图片' },
			rt.ArrayItem{
				key: 'This will restore the original header image. You will not be able to restore any customizations.'
				val: '这将重置页眉图片。之后，您将无法还原任何自定义元素。'
			},
			rt.ArrayItem{ key: 'Reset Image', val: '重置图片' },
			rt.ArrayItem{ key: 'Remove Header Image', val: '移除页眉图片' },
			rt.ArrayItem{
				key: 'This will remove the header image. You will not be able to restore any customizations.'
				val: '这将移除页眉图片。之后，您将无法还原任何自定义元素。'
			},
			rt.ArrayItem{ key: 'Default Images', val: '默认图片' },
			rt.ArrayItem{ key: 'Delete this comment permanently', val: '永久删除此评论' },
			rt.ArrayItem{
				key: 'Restore this comment from the Trash'
				val: '从回收站中恢复此评论'
			},
			rt.ArrayItem{ key: 'Allow comments', val: '允许评论' },
			rt.ArrayItem{
				key: '<strong>Discussion</strong> &mdash; You can turn comments and pings on or off, and if there are comments on the post, you can see them here and moderate them.'
				val: '<strong>讨论</strong>——您可以开启或关闭评论和 Ping 功能。若该篇文章有评论，您可以在这里浏览、审核评论。'
			},
			rt.ArrayItem{
				key: '<strong>%s</strong> &mdash; This allows you to associate an image with your post without inserting it. This is usually useful only if your theme makes use of the image as a post thumbnail on the home page, a custom header, etc.'
				val: '<strong>%s</strong>——这让您可以使用文章里的图片而不用重新插入它。通常您的主题在首页或自定义页首时使用特色图片功能作为缩略图时才用得到。'
			},
			rt.ArrayItem{
				key: '<strong>Title</strong> &mdash; Enter a title for your post. After you enter a title, you&#8217;ll see the permalink below, which you can edit.'
				val: '<strong>标题</strong>——为您的文章选择标题。在输入完标题后，您可以在下方看到固定链接，您也可以对此加以编辑。'
			},
			rt.ArrayItem{
				key: 'Hovering over a row in the posts list will display action links that allow you to manage your post. You can perform the following actions:'
